  var start := 0;
  for var index := 0 to s.Length - 1 do
  begin
    var ch := s[index];
    if used.ContainsKey(ch) and (start <= used[ch]) then
      start := used[ch] + 1;
    var currentLength := index - start + 1;
    if currentLength > maxLength then
