  for var i := 2 to n do
  begin
    dp[i] := i;
    for var j := 2 to i div 2 do
      if i mod j = 0 then
      begin
        var candidate := dp[j] + dp[i div j];
        if candidate < dp[i] then
          dp[i] := candidate;
      end;
  end;
