function MaximumBags(const capacity, rocks: array of integer; additionalRocks: integer): integer;
begin
  var gaps := new List<integer>;
  for var i := 0 to capacity.Length - 1 do
    gaps.Add(capacity[i] - rocks[i]);
  gaps.Sort;
  var filled := 0;
  foreach var gap in gaps do
  begin
    if gap = 0 then
    begin
      Inc(filled);
      continue;
    end;
    if additionalRocks < gap then
