  var n := matrix.Length;
  var m := matrix[0].Length;
  var dp := new integer[n, m];
  var sumval := 0;
  for var i := 0 to n - 1 do
  begin
    dp[i,0] := matrix[i][0];
    sumval += dp[i,0];
  end;
  for var j := 1 to m - 1 do
  begin
    dp[0,j] := matrix[0][j];
    sumval += dp[0,j];
  end;
  for var i := 1 to n - 1 do
    for var j := 1 to m - 1 do
    begin
      if matrix[i][j] = 1 then
      begin
        dp[i,j] := Min(dp[i-1,j], Min(dp[i,j-1], dp[i-1,j-1])) + 1;
        sumval += dp[i,j];
      end
      else
        dp[i,j] := 0;
    end;
  Result := sumval;
end;

function LargestRectangleArea(matrix: array of array of integer): integer;
begin
  if matrix = nil then
  begin
    Result := 0;
    exit;
  end;
  var n := matrix[0].Length;
  var height := new integer[n + 1]; // sentinel at end
  var maxArea := 0;
  for var r := 0 to matrix.Length - 1 do
  begin
    for var i := 0 to n - 1 do
      if matrix[r][i] = 1 then
        height[i] := height[i] + 1
      else
        height[i] := 0;
    // stack using dynamic array of integers
    var st := new List<integer>;
    st.Add(-1);
    for var i := 0 to n do
    begin
      var curH := height[i];
      while (st.Count > 1) and (curH < height[st[st.Count - 1]]) do
      begin
        var h := height[st[st.Count - 1]];
        st.RemoveAt(st.Count - 1);
        var w := i - 1 - st[st.Count - 1];
        maxArea := Max(maxArea, h * w);
      end;
      st.Add(i);
    end;
  end;
  Result := maxArea;
end;

