function OneEdit(a, b: string): boolean;
begin
  var la := a.Length;
  var lb := b.Length;

  if Abs(la - lb) > 1 then
  begin
    Result := False;
    exit;
  end;

  var i := 0;
  var j := 0;
  var diff := 0;

  while (i < la) and (j < lb) do
  begin
    if a[i] = b[j] then
    begin
      i += 1;
      j += 1;
    end
    else
    begin
      diff += 1;
      if diff > 1 then
      begin
        Result := False;
        exit;
      end;

      if la > lb then i += 1
      else if lb > la then j += 1
      else begin i += 1; j += 1; end;
    end;
  end;

  diff += (la - i) + (lb - j);

  Result := diff = 1;
end;

