      st.Add(ch)
    else if (ch = ')') or (ch = ']') or (ch = '}') then
    begin
      if st.Count = 0 then
      begin
        Result := False;
        exit;
      end;

      var top := st[st.Count - 1];
      st.RemoveAt(st.Count - 1);

      if (ch = ')') and (top <> '(') then begin Result := False; exit; end;
      if (ch = ']') and (top <> '[') then begin Result := False; exit; end;
      if (ch = '}') and (top <> '{') then begin Result := False; exit; end;
    end;
  end;

  Result := st.Count = 0;
end;

