function NumWaysToMakeChange(n: integer; denoms: array of integer): integer;
begin
  var ways := ArrFill(n + 1, 0);
  ways[0] := 1;
  foreach var denom in denoms do
    for var amount := 1 to n do
      if denom <= amount then
        ways[amount] += ways[amount - denom];
  Result := ways[n];
end;

