function FindFibonacciNumbers(num: integer): integer;
begin
  if num = 0 then
  begin
    Result := 0;
    exit;
  end;
  var fibs := Lst(1, 1);
  while fibs.Last < num do
    fibs.Add(fibs[fibs.Count - 1] + fibs[fibs.Count - 2]);
  var count := 0;
  while num > 0 do
  begin
    var idx := fibs.Count - 1;
    while fibs[idx] > num do
      idx -= 1;
    num -= fibs[idx];
    count += 1;
  end;
  Result := count;
end;

function LongestZeros(n: integer): integer;
begin
  var binary := Convert.ToString(n, 2);
  var maxZeros := 0;
  var currentZeros := 0;
  var started := False;
  foreach var bit in binary do
  begin
    if bit = '0' then
    begin
      if started then
        currentZeros += 1
      else
      begin
        started := True;
        currentZeros := 1;
      end;
    end
    else
    begin
      if started then
      begin
        maxZeros := Max(maxZeros, currentZeros);
        currentZeros := 0;
      end;
    end;
  end;
  Result := maxZeros;
end;

