  var C := matrix.GetLength(1);
  foreach var tuple in zeros do
  begin
    var first := tuple[0];
    var second := tuple[1];
    if (first < 0) or (first >= R) or (second < 0) or (second >= C) then
    begin
      Result := False;
      exit;
    end;
    for var k := 0 to C - 1 do
      if (matrix[first, k] = 0) and not zeros.Contains((first, k)) then
      begin
        Result := False;
        exit;
      end;
    for var k := 0 to R - 1 do
      if (matrix[k, second] = 0) and not zeros.Contains((k, second)) then
      begin
        Result := False;
        exit;
      end;
  end;
  Result := True;
end;

