function SubarrayProductLessThanK(nums: array of integer; k: integer): integer;
begin
  if k <= 1 then
  begin
    Result := 0;
    exit;
  end;
  var prod := 1;
  var ans := 0;
  var left := 0;
  for var right := 0 to nums.Length - 1 do
  begin
    prod *= nums[right];
    while prod >= k do
    begin
      prod := prod div nums[left];
      left += 1;
    end;
    ans += right - left + 1;
  end;
  Result := ans;
end;

