function BinarySearchOccurrence(arr: array of integer; target: integer): integer;

  function FindLeftIndex(arr: array of integer; target: integer): integer;
  begin
    var left := 0;
    var right := arr.Length - 1;
    while left <= right do
    begin
      var mid := left + (right - left) div 2;
      if arr[mid] < target then
        left := mid + 1
      else
        right := mid - 1;
    end;
    Result := left;
  end;

  function FindRightIndex(arr: array of integer; target: integer): integer;
  begin
    var left := 0;
    var right := arr.Length - 1;
    while left <= right do
    begin
      var mid := left + (right - left) div 2;
      if arr[mid] <= target then
        left := mid + 1
      else
        right := mid - 1;
    end;
    Result := right;
  end;

begin
  var leftIndex := FindLeftIndex(arr, target);
  if (leftIndex = arr.Length) or (arr[leftIndex] <> target) then
  begin
    Result := 0;
    exit;
  end;
  var rightIndex := FindRightIndex(arr, target);
  Result := rightIndex - leftIndex + 1;
end;

