function FindCombinations(nums: array of integer; target: integer): List<List<integer>>;

  procedure Dfs(path: List<integer>; index: integer; remaining: integer; resultList: List<List<integer>>);
  begin
    if remaining = 0 then
    begin
      resultList.Add(new List<integer>(path));
      exit;
    end;
    for var i := index to nums.Length - 1 do
    begin
      if remaining - nums[i] < 0 then break;
      path.Add(nums[i]);
      Dfs(path, i, remaining - nums[i], resultList);
      path.RemoveAt(path.Count - 1);
    end;
  end;

begin
  var resultList := new List<List<integer>>;
  Dfs(new List<integer>, 0, target, resultList);
  Result := resultList;
end;

function MaxMeetingRooms(meetings: array of (integer, integer)): integer;
