    ] := True;
  for var i := 1 to s.Length do
    for var j := 1 to p.Length do
    begin
      if (p[j - 1
    ] = s[i - 1
    ]) or (p[j - 1
    ] = '.') then
        dp[i, j
    ] := dp[i - 1, j - 1
    ]
      else if p[j - 1
    ] = '*' then
        dp[i, j
    ] := dp[i, j - 2
    ] or (dp[i - 1, j
    ] and ((s[i - 1
    ] = p[j - 2
    ]) or (p[j - 2
    ] = '.')));
    end;
  Result := dp[s.Length, p.Length
