  var count := new Dictionary<char, integer>;
  foreach var c in s do
  begin
    if count.ContainsKey(c) then
      count[c] := count[c] + 1
    else
      count[c] := 1;
  end;

  var res := 0;
  var hasOdd := False;

  foreach var v in count.Values do
  begin
    if v mod 2 = 0 then
      res += v
    else
    begin
      res += v - 1;
      hasOdd := True;
    end;
  end;

  if hasOdd then
    res += 1;

  Result := res;
end;

