    ], nums[
      1
    ]);
  var secondLargest := Min(nums[
      0
    ], nums[
      1
    ]);
  for var i := 2 to nums.Length - 1 do
  begin
    if nums[i
    ] > largest then
    begin
      secondLargest := largest;
      largest := nums[i
    ];
    end
    else if (nums[i
    ] > secondLargest) and (nums[i
    ] <> largest) then
