    ];
  for var i := 0 to m do
    for var j := 0 to n do
    begin
      if i = 0 then
        dp[i, j
    ] := j
      else if j = 0 then
        dp[i, j
    ] := i
      else if str1[i
    ] = str2[j
    ] then
        dp[i, j
    ] := dp[i - 1, j - 1
    ]
      else
        dp[i, j
    ] := 1 + Min(Min(dp[i - 1, j
    ], dp[i, j - 1
    ]), dp[i - 1, j - 1
    ]);
    end;
  Result := dp[m, n
    ];
end;

