  begin
    if i mod 2 = 0 then
      res.Add(lst[i])
    else
    begin
      res.Add(oddIndices[oddIdx]);
      oddIdx += 1;
    end;
  end;

  Result := res.ToArray;
end;

function IsLargestPalindrome(n: integer): integer;
begin
  var largestPalindrome := 0;
  var startNum := Round(Power(10, n - 1));
  var endNum := Round(Power(10, n)) - 1;

  for var i := startNum to endNum do
  begin
    for var j := i to endNum do
    begin
      var product := i * j;
      var productStr := product.ToString;
      var reversedStr := new string(productStr.Reverse.ToArray);

      if (productStr = reversedStr) and (product > largestPalindrome) then
        largestPalindrome := product;
    end;
  end;
  Result := largestPalindrome;
end;

function MaxConsecutive1s(nums: array of integer; k: integer): integer;
begin
  var left := 0;

  for var right := 0 to nums.Length - 1 do
  begin
    if nums[right] = 0 then
      k -= 1;

    if k < 0 then
    begin
      if nums[left] = 0 then
        k += 1;
      left += 1;
    end;
  end;

  Result := nums.Length - left;
end;

function IsPrime(num: integer): boolean;
begin
  if num < 2 then
  begin
    Result := False;
    exit;
  end;
  for var i := 2 to Round(Sqrt(num)) do
    if num mod i = 0 then
    begin
      Result := False;
      exit;
    end;
  Result := True;
end;

function SumOfFirstNPrimes(n: integer): integer;
begin
  var primeCount := 0;
  var sumPrimes := 0;
  var num := 2;

  while primeCount < n do
  begin
    if IsPrime(num) then
    begin
      primeCount += 1;
      sumPrimes += num;
    end;
    num += 1;
  end;

  Result := sumPrimes;
end;

