function ValidCuboid(cuboid: Cuboid): integer?;
begin
  if (cuboid.MinX > cuboid.MaxX) or (cuboid.MinY > cuboid.MaxY) or (cuboid.MinZ > cuboid.MaxZ) then
    Result := nil
  else
    Result := (cuboid.MaxX - cuboid.MinX + 1) * (cuboid.MaxY - cuboid.MinY + 1) * (cuboid.MaxZ - cuboid.MinZ + 1);
end;

function NumPairsDivisible(arr: array of integer; divider: integer): integer;
begin
  var d := new Dictionary<integer, integer>;
  var count := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    var v := arr[i];
    var remainder := v mod divider;

    var c : integer;
    if remainder = 0 then
      count += d.TryGetValue(0, c) ? c : 0
    else
      count += d.TryGetValue(divider - remainder, c) ? c : 0;

    if d.ContainsKey(remainder) then
      d[remainder] += 1
    else
      d[remainder] := 1;
  end;

  Result := count;
end;

function LongestBitonicSubsequence(arr: array of integer): integer;
begin
  var n := arr.Length;
  var inc := ArrFill(n, 1);
  var dec := ArrFill(n, 1);

  for var i := 1 to n - 1 do
    for var j := 0 to i - 1 do
      if (arr[i] > arr[j]) and (inc[i] < inc[j] + 1) then
        inc[i] := inc[j] + 1;

  for var i := n - 2 downto 0 do
    for var j := n - 1 downto i + 1 do
      if (arr[i] > arr[j]) and (dec[i] < dec[j] + 1) then
        dec[i] := dec[j] + 1;

  var maxLen := 0;
  for var i := 0 to n - 1 do
    maxLen := Max(maxLen, inc[i] + dec[i] - 1);

  Result := maxLen;
end;

function MaxProfit(prices: array of integer): integer;
