  Result := results;
end;

function DifferenceSortedArrays(arr1, arr2: array of integer): List<integer>;
begin
  var difference := new List<integer>;
  var p1 := 0;
  var p2 := 0;

  while (p1 < arr1.Length) and (p2 < arr2.Length) do
  begin
    if arr1[p1] < arr2[p2] then
    begin
      difference.Add(arr1[p1]);
      p1 += 1;
    end
    else if arr1[p1] > arr2[p2] then
      p2 += 1
    else
    begin
      p1 += 1;
      p2 += 1;
    end;
  end;

  while p1 < arr1.Length do
  begin
    difference.Add(arr1[p1]);
    p1 += 1;
  end;

  Result := difference;
end;

