  for var i := words.Length - 1 downto 0 do
  begin
    var word := words[i];
    if word.Length > 0 then
      reversedWords.Add(word[1].ToUpper + word.Substring(2).ToLower)
    else
      reversedWords.Add(word);
  end;

  Result := string.Join(' ', reversedWords);
end;

function Merge(var arr, tempArr: array of integer; left, mid, right: integer): integer;
begin
  var i := left;
  var j := mid + 1;
  var k := left;
  var invCount := 0;

  while (i <= mid) and (j <= right) do
  begin
    if arr[i] <= arr[j] then
    begin
      tempArr[k] := arr[i];
      k += 1;
      i += 1;
    end
    else
    begin
      tempArr[k] := arr[j];
      invCount += (mid - i + 1);
      k += 1;
      j += 1;
    end;
  end;

  while i <= mid do
  begin
    tempArr[k] := arr[i];
    k += 1;
    i += 1;
  end;

  while j <= right do
  begin
    tempArr[k] := arr[j];
    k += 1;
    j += 1;
  end;

  for var idx := left to right do
    arr[idx] := tempArr[idx];

  Result := invCount;
end;

function MergeSort(var arr, tempArr: array of integer; left, right: integer): integer;
begin
  var invCount := 0;
  if left < right then
  begin
    var mid := (left + right) div 2;

    invCount += MergeSort(arr, tempArr, left, mid);
    invCount += MergeSort(arr, tempArr, mid + 1, right);
    invCount += Merge(arr, tempArr, left, mid, right);
  end;
  Result := invCount;
end;

function CountInversions(arr: array of integer): integer;
begin
  var tempArr := new integer[arr.Length];
  Result := MergeSort(arr, tempArr, 0, arr.Length - 1);
end;

function FindShortestPathCost(grid: array of array of char): integer;
begin
  if (grid.Length = 0) or (grid[0].Length = 0) then
  begin
    Result := -1;
    exit;
  end;

  var rows := grid.Length;
  var cols := grid[0].Length;
  var directions := Arr((0, 1), (1, 0), (0, -1), (-1, 0));
  var start: (integer, integer) := nil;
  var finish: (integer, integer) := nil;

  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
    begin
      if grid[i][j] = 'S' then
        start := (i, j)
      else if grid[i][j] = 'E' then
        finish := (i, j);
    end;

  if (start = nil) or (finish = nil) then
  begin
    Result := -1;
    exit;
  end;

  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((start.Item1, start.Item2, 0));
  var visited := new HashSet<(integer, integer)>;
  visited.Add((start.Item1, start.Item2));

  while queue.Count > 0 do
  begin
    var (x, y, cost) := queue.Dequeue;
    if (x, y) = finish then
    begin
      Result := cost;
      exit;
    end;

    foreach var (dx, dy) in directions do
    begin
      var nx := x + dx;
      var ny := y + dy;
      if (nx >= 0) and (nx < rows) and (ny >= 0) and (ny < cols) and 
         (grid[nx][ny] <> 'X') and not visited.Contains((nx, ny)) then
      begin
        visited.Add((nx, ny));
        queue.Enqueue((nx, ny, cost + 1));
      end;
    end;
  end;

  Result := -1;
end;

