function CalculateStats(numbers: array of integer): (integer, integer, real);
begin
  if numbers.Length = 0 then
  begin
    Result := (0, 0, 0);
    exit;
  end;

  var maxNum := numbers[0];
  var minNum := numbers[0];
  var total := 0;

  foreach var num in numbers do
  begin
    if num > maxNum then
      maxNum := num;
    if num < minNum then
      minNum := num;
    total += num;
  end;

  var avg := total / numbers.Length;
  Result := (maxNum, minNum, avg);
end;

function FindPivot(nums: array of integer): integer;
begin
  var left := 0;
  var right := nums.Length - 1;

  while left < right do
  begin
    var mid := (left + right) div 2;
    if nums[mid] > nums[right] then
      left := mid + 1
    else
      right := mid;
  end;
  Result := left;
end;

function BinarySearch(nums: array of integer; target, left, right: integer): integer;
begin
  while left <= right do
  begin
    var mid := (left + right) div 2;
    if nums[mid] = target then
    begin
      Result := mid;
      exit;
    end
    else if nums[mid] < target then
      left := mid + 1
    else
      right := mid - 1;
  end;
  Result := -1;
end;

function FindInRotatedArray(nums: array of integer; target: integer): integer;
begin
  var pivot := FindPivot(nums);
  if (pivot = 0) or (target < nums[0]) then
    Result := BinarySearch(nums, target, pivot, nums.Length - 1)
  else
    Result := BinarySearch(nums, target, 0, pivot - 1);
end;

function LargestSubarrayLength(nums: array of integer; k: integer): integer;
begin
  var i := 0;
  var ans := 0;
  var win := new Dictionary<integer, integer>;

  for var j := 0 to nums.Length - 1 do
  begin
    if not win.ContainsKey(nums[j]) then
      win[nums[j]] := 0;

    if win[nums[j]] = 0 then
      k -= 1;

    win[nums[j]] += 1;

    while k < 0 do
    begin
      win[nums[i]] -= 1;
      if win[nums[i]] = 0 then
        k += 1;
      i += 1;
    end;

    ans := Max(ans, j - i + 1);
  end;

  Result := ans;
end;

