function ProductWithoutMultiplication(x, y: integer): integer;
begin
  if y = 0 then
    Result := 0
  else if y > 0 then
    Result := x + ProductWithoutMultiplication(x, y - 1)
  else
    Result := -ProductWithoutMultiplication(x, -y);
