function StepCount(n: integer): integer;
begin
  var count := 0;
  var tempN := n;

  while tempN > 1 do
  begin
    if tempN mod 2 = 0 then
      tempN := tempN div 2
    else if (tempN = 3) or (tempN mod 4 = 1) then
      tempN := tempN - 1
    else
      tempN := tempN + 1;
    count += 1;
  end;

  Result := count;
end;

function CalculatePoisonDuration(timeSeries: array of integer; duration: integer): integer;
begin
  if timeSeries.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var res := 0;
  var n := timeSeries.Length;

  for var i := 1 to n - 1 do
  begin
    var diff := timeSeries[i] - timeSeries[i - 1];
    if diff < duration then
      res += diff
    else
      res += duration;
  end;

  Result := res + duration;
end;

