    if not adj.ContainsKey(v) then
      adj[v] := new HashSet<integer>;

    adj[u].Add(v);
    adj[v].Add(u);
  end;

  var parents := new integer[n];
  var ranks := new integer[n];

  for var i := 0 to n - 1 do
    parents[i] := i;

  var ans := 0;
  var valsNodesMap := new Dictionary<integer, List<integer>>;

  for var i := 0 to n - 1 do
