  end;

  var maxVal := new integer[n];
  maxVal[0] := arr[0];

  for var i := 1 to n - 1 do
    maxVal[i] := Max(arr[i], maxVal[i-1]);

  var res := arr[0];
  for var i := 1 to n - 1 do
  begin
    if k > 0 then
    begin
      res := Max(res, maxVal[Min(i + k, n - 1)]);
      maxVal[i] := Max(maxVal[i], res);
    end
    else
      res := maxVal[i];
  end;

  Result := res;
end;

