function FindIndex(numbers: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := numbers.Length - 1;

  while left <= right do
  begin
    var mid := left + (right - left) div 2;

    if numbers[mid] = target then
    begin
      if (mid = 0) or (numbers[mid - 1] < target) then
      begin
        Result := mid;
        exit;
      end;
      right := mid - 1;
    end
    else if numbers[mid] < target then
      left := mid + 1
    else
      right := mid - 1;
  end;

  Result := -1;
end;

