    var length := s.Length;

    for var i := 1 to length - 1 do
    begin
      var low := i - 1;
      var high := i;
      while (low >= 0) and (high < length) and (s[low+1] = s[high+1]) do
      begin
        if (high - low + 1) > maxLength then
        begin
          startIndex := low;
          maxLength := high - low + 1;
        end;
        low -= 1;
        high += 1;
      end;

      low := i - 1;
      high := i + 1;
      while (low >= 0) and (high < length) and (s[low+1] = s[high+1]) do
      begin
        if (high - low + 1) > maxLength then
        begin
          startIndex := low;
          maxLength := high - low + 1;
