  sizeList.Sort;

  var res := 0;
  var i := 0;
  while (i < greedList.Count) and (res < sizeList.Count) do
  begin
    if greedList[i] <= sizeList[res] then
      i += 1;
    res += 1;
  end;
  Result := i;
end;

procedure GenerateCombinations(lst: array of integer; k: integer; start: integer; current: List<integer>; var result: List<List<integer>>);
begin
  if current.Count = k then
  begin
    result.Add(new List<integer>(current));
    exit;
  end;

  for var i := start to lst.Length - 1 do
  begin
    current.Add(lst[i]);
    GenerateCombinations(lst, k, i + 1, current, result);
    current.RemoveAt(current.Count - 1);
  end;
end;

