function BalancedBinaryTrees(n: integer): integer;
begin
  if (n = 0) or (n = 1) then
    Result := 1
  else
  begin
    var C := new integer[n+1];
    C[0] := 1;
    C[1] := 1;

    for var i := 2 to n do
    begin
      C[i] := 0;
      for var j := 0 to i - 1 do
        C[i] := C[i] + C[j] * C[i-j-1];
    end;

    Result := C[n];
