  for var i := n - 1 downto 0 do
  begin
    dp[i,i] := 1;
    for var j := i + 1 to n - 1 do
      if s[i+1] = s[j+1] then
        dp[i,j] := dp[i+1,j-1] + 2
      else
        dp[i,j] := Max(dp[i+1,j], dp[i,j-1]);
  end;

  Result := dp[0,n-1];
end;

function HappyNumber(n: integer): boolean;

  function GetNext(number: integer): integer;
  begin
    var totalSum := 0;
    var num := number;
    while num > 0 do
    begin
      var digit := num mod 10;
      totalSum += digit * digit;
      num := num div 10;
    end;
    Result := totalSum;
  end;

begin
  var seen := new HashSet<integer>;
  var current := n;
  while (current <> 1) and (not seen.Contains(current)) do
  begin
    seen.Add(current);
    current := GetNext(current);
  end;
  Result := current = 1;
end;

function CanBePalindrome(s: string): boolean;
begin
  var letterCount := new Dictionary<char, integer>;
  foreach var letter in s do
    if char.IsLetterOrDigit(letter) then
    begin
      var lowerLetter := letter.ToLower;
      if letterCount.ContainsKey(lowerLetter) then
        letterCount[lowerLetter] += 1
      else
        letterCount.Add(lowerLetter, 1);
    end;

  var oddCount := 0;
  foreach var count in letterCount.Values do
    if count mod 2 <> 0 then
      oddCount += 1;

  Result := oddCount <= 1;
end;

