function MinSubArrayLength(nums: array of integer; target: integer): integer;
begin
  var n := nums.Length;
  var minLen := n + 1;
  var left := 0;
  var currentSum := 0;

  for var right := 0 to n - 1 do
  begin
    currentSum += nums[right];
    while currentSum >= target do
    begin
      minLen := Min(minLen, right - left + 1);
      currentSum -= nums[left];
      left += 1;
    end;
  end;

  if minLen <= n then
    Result := minLen
  else
    Result := 0;
end;

function MaxSubArrayProduct(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var maxProduct := nums[0];
  var minProduct := nums[0];
  var resultVal := maxProduct;

  for var i := 1 to nums.Length - 1 do
  begin
    var temp := maxProduct;
    maxProduct := Max(nums[i], Max(maxProduct * nums[i], minProduct * nums[i]));
    minProduct := Min(nums[i], Min(temp * nums[i], minProduct * nums[i]));
    resultVal := Max(resultVal, maxProduct);
  end;

  Result := resultVal;
end;

function CanBeSumOfThreeConsecutive(num: integer): boolean;
begin
  var a := (num - 3) / 3;
  if a = Trunc(a) then
    Result := True
  else
    Result := False;
end;

function ConvertToPigLatin(word: string): string;
begin
  var vowels := 'aeiou';
  if word[1].ToLower in vowels then
    Result := word + 'way'
  else
    Result := word.Substring(1) + word[1] + 'ay';
end;

function CountPatternOverlap(text, pattern: string): integer;
begin
  if pattern.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var count := 0;
  var start := 0;
  var pos := text.IndexOf(pattern, start);

  while pos <> -1 do
  begin
    count += 1;
    start := pos + 1;
    pos := text.IndexOf(pattern, start);
  end;

  Result := count;
end;

function FindOddOccurrence(arr: array of integer): integer;
begin
  var res := 0;
  foreach var i in arr do
    res := res xor i;
  Result := res;
end;

function DigitFrequency(number, digit: integer): integer;
begin
  var count := 0;
  var num := number;
  while num > 0 do
  begin
    if num mod 10 = digit then
      count += 1;
    num := num div 10;
  end;
  Result := count;
end;

function MergeStrings(word1, word2: string): string;
begin
  var outStr := '';
  var index1 := 0;
  var index2 := 0;

  while (index1 < word1.Length) or (index2 < word2.Length) do
  begin
    if index1 < word1.Length then
      outStr += word1[index1+1];
    if index2 < word2.Length then
      outStr += word2[index2+1];
    index1 += 1;
    index2 += 1;
  end;

  Result := outStr;
end;

function IsPalindromeIgnore(s: string): boolean;
begin
  var filtered := '';
  foreach var ch in s do
    if char.IsLetterOrDigit(ch) then
      filtered += ch.ToLower;

  Result := filtered = ReverseString(filtered);
end;

function LeastSquares(n: integer): integer;
begin
  var dp := new integer[n + 1];
  for var i := 1 to n do
  begin
    dp[i] := i;
    for var j := 1 to Trunc(Sqrt(i)) do
      dp[i] := Min(dp[i], dp[i - j * j] + 1);
  end;
  Result := dp[n];
end;

function MaxSumKConsecutive(arr: array of integer; k: integer): integer;
begin
  if arr.Length < k then
  begin
    Result := 0;
    exit;
  end;

  var maxSum := 0;
  var currentSum := 0;

  for var i := 0 to k - 1 do
    currentSum += arr[i];

  maxSum := currentSum;

  for var i := k to arr.Length - 1 do
  begin
    currentSum += arr[i] - arr[i - k];
    maxSum := Max(maxSum, currentSum);
  end;

  Result := maxSum;
end;

function CanCompleteCircuit(gas, cost: array of integer): integer;
begin
  var gasSum := gas.Sum;
  var costSum := cost.Sum;
  if gasSum < costSum then
  begin
    Result := -1;
    exit;
  end;

  var n := gas.Length;
  var tank := 0;
  var start := 0;

  for var i := 0 to n - 1 do
  begin
    tank += gas[i] - cost[i];
    if tank < 0 then
    begin
      tank := 0;
      start := i + 1;
    end;
  end;

  Result := start;
end;

function IsPossibleDivide(nums: array of integer; k: integer): boolean;
begin
  if nums.Length mod k <> 0 then
  begin
    Result := False;
    exit;
  end;

  var numCounts := new Dictionary<integer, integer>;
  foreach var num in nums do
    if numCounts.ContainsKey(num) then
      numCounts[num] += 1
    else
      numCounts.Add(num, 1);

  var sortedKeys := numCounts.Keys.ToList;
  sortedKeys.Sort;

  foreach var key in sortedKeys do
  begin
    if numCounts[key] > 0 then
    begin
      for var i := 1 to k - 1 do
      begin
        if (not numCounts.ContainsKey(key + i)) or (numCounts[key + i] < numCounts[key]) then
        begin
          Result := False;
          exit;
        end;
        numCounts[key + i] -= numCounts[key];
      end;
    end;
  end;

  Result := True;
end;

function MinGuessCost(n: integer): integer;
begin
  var pay := new integer[n+1, n+1];

  for var i := n - 1 downto 0 do
    for var j := i + 1 to n - 1 do
    begin
      var minVal := integer.MaxValue;
      for var k := i to j do
        minVal := Min(minVal, k + 1 + Max(pay[i, k-1], pay[k+1, j]));
      pay[i,j] := minVal;
    end;

  Result := pay[0, n-1];
end;

function GetUglyNumbers(n: integer): array of integer;
begin
  var ugly := new integer[n];
  ugly[0] := 1;
  var i2 := 0;
  var i3 := 0;
  var i5 := 0;
  var nextMultipleOf2 := 2;
  var nextMultipleOf3 := 3;
  var nextMultipleOf5 := 5;

  for var i := 1 to n - 1 do
  begin
    var nextUgly := Min(nextMultipleOf2, Min(nextMultipleOf3, nextMultipleOf5));
    ugly[i] := nextUgly;

    if nextUgly = nextMultipleOf2 then
    begin
      i2 += 1;
      nextMultipleOf2 := ugly[i2] * 2;
    end;

    if nextUgly = nextMultipleOf3 then
    begin
      i3 += 1;
      nextMultipleOf3 := ugly[i3] * 3;
    end;

    if nextUgly = nextMultipleOf5 then
    begin
      i5 += 1;
      nextMultipleOf5 := ugly[i5] * 5;
    end;
  end;

  Result := ugly;
end;

function SearchRotatedArray(nums: array of integer; target: integer): integer;

  function FindRotationPoint(arr: array of integer): integer;
  begin
    var low := 0;
    var high := arr.Length - 1;
    while low < high do
    begin
      var mid := low + (high - low) div 2;
      if arr[mid] > arr[high] then
        low := mid + 1
      else
        high := mid;
    end;
    Result := low;
  end;

  function BinarySearch(low, high: integer; targetVal: integer; arr: array of integer): integer;
  begin
    while low <= high do
    begin
      var mid := low + (high - low) div 2;
      if arr[mid] = targetVal then
      begin
        Result := mid;
        exit;
      end
      else if arr[mid] < targetVal then
        low := mid + 1
      else
        high := mid - 1;
    end;
    Result := -1;
  end;

begin
  var rotationPoint := FindRotationPoint(nums);

  if nums[rotationPoint] = target then
  begin
    Result := rotationPoint;
    exit;
  end;

  if nums[0] = target then
  begin
    Result := 0;
    exit;
  end;

  if rotationPoint = 0 then
    Result := BinarySearch(0, nums.Length - 1, target, nums)
  else if target < nums[0] then
    Result := BinarySearch(rotationPoint, nums.Length - 1, target, nums)
  else
    Result := BinarySearch(0, rotationPoint - 1, target, nums);
end;

function FindSmallestSum(arr: array of integer): integer;
begin
  var sortedArr := arr.ToList;
  sortedArr.Sort;
  Result := sortedArr[0] + sortedArr[1];
end;

function LongestSubstring(s: string): integer;
begin
  var startIndex := 0;
  var maxLength := 0;
  var dic := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    if dic.ContainsKey(ch) and (startIndex <= dic[ch]) then
      startIndex := dic[ch] + 1
    else
      maxLength := Max(maxLength, i - startIndex + 1);

    dic[ch] := i;
  end;

  Result := maxLength;
end;

function FindFactorialUsingRecursion(n: integer): integer;
begin
  if n = 0 then
    Result := 1
  else
    Result := n * FindFactorialUsingRecursion(n - 1);
end;

function IsOverlapping(A, B, C, D, E, F, G, H: integer): boolean;
begin
  if (E >= C) or (G <= A) then
    Result := False
  else if (F >= D) or (H <= B) then
    Result := False
  else
    Result := True;
end;

function Hanoi(n: integer): integer;
begin
  if n = 1 then
    Result := 1
  else
    Result := 2 * Hanoi(n - 1) + 1;
end;

function FindMissingNumbers(nums: array of integer): array of integer;
begin
  var n := nums.Length;
  var numList := nums.ToList;

  for var i := 0 to n - 1 do
    while (numList[i] <> i + 1) and (numList[numList[i] - 1] <> numList[i]) do
    begin
      var temp := numList[numList[i] - 1];
      numList[numList[i] - 1] := numList[i];
      numList[i] := temp;
    end;

  Result := Range(1, n).Where(i -> numList[i - 1] <> i).ToArray;
end;

function MaxWater(height: array of integer): integer;
begin
  var extendedHeight := new integer[height.Length + 2];
  extendedHeight[0] := 0;
  for var i := 0 to height.Length - 1 do
    extendedHeight[i + 1] := height[i];
  extendedHeight[extendedHeight.Length - 1] := 0;

  var leftMax := new integer[extendedHeight.Length];
  var rightMax := new integer[extendedHeight.Length];

  for var i := 1 to extendedHeight.Length - 1 do
    leftMax[i] := Max(extendedHeight[i], leftMax[i - 1]);

  for var i := extendedHeight.Length - 2 downto 0 do
    rightMax[i] := Max(extendedHeight[i], rightMax[i + 1]);

  var res := 0;
  for var i := 1 to extendedHeight.Length - 2 do
    res += Min(leftMax[i], rightMax[i]) - extendedHeight[i];

  Result := res;
end;

function CountDecodeWays(s: string): integer;
begin
  if (s.Length = 0) or (s[1] = '0') then
  begin
    Result := 0;
    exit;
  end;

  var n := s.Length;
  var dp := new integer[n + 1];
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
  begin
    if s[i] <> '0' then
      dp[i] := dp[i - 1];

    var twoDigit := StrToInt(s.Substring(i - 2, 2));
    if (s[i - 1] <> '0') and (twoDigit <= 26) then
      dp[i] += dp[i - 2];
  end;

  Result := dp[n];
end;

function GenerateSquareMatrix(n: integer): array [,] of integer;
begin
  Result := new integer[n, n];
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      Result[i, j] := (i * n + j) * (i * n + j);
end;

function FindMaxDifference(arr: array of integer): integer;
begin
  if arr.Length < 2 then
  begin
    Result := 0;
    exit;
  end;

  var maxDiff := arr[1] - arr[0];
  var minElement := arr[0];

  for var i := 1 to arr.Length - 1 do
  begin
    if arr[i] - minElement > maxDiff then
      maxDiff := arr[i] - minElement;
    if arr[i] < minElement then
      minElement := arr[i];
  end;

  Result := maxDiff;
end;

function SequenceCheck(nums: array of integer): boolean;
begin
  for var i := 0 to nums.Length - 3 do
    if (nums[i] = 1) and (nums[i + 1] = 2) and (nums[i + 2] = 3) then
    begin
      Result := True;
      exit;
    end;
  Result := False;
end;

function ReplaceLast(lst: List<List<integer>>; newLst: List<integer>): List<List<integer>>;
begin
  lst[lst.Count - 1] := newLst;
  Result := lst;
end;

function ShortestRepeatingPattern(s: string): integer;
begin
  for var i := 1 to s.Length div 2 do
    if s.Length mod i = 0 then
      if s.Substring(0, i) * (s.Length div i) = s then
      begin
        Result := i;
        exit;
      end;
  Result := -1;
end;

function WordCounter(sentences: array of string): Dictionary<string, integer>;
begin
  var wordCount := new Dictionary<string, integer>;

  foreach var sentence in sentences do
  begin
    var words := sentence.Split(' ');
    foreach var word in words do
      if wordCount.ContainsKey(word) then
        wordCount[word] += 1
      else
        wordCount.Add(word, 1);
  end;

  Result := wordCount;
end;

function PowerList(lst: array of integer; pow: integer): array of integer;
begin
  var res := new integer[lst.Length];
  for var i := 0 to lst.Length - 1 do
  begin
    var num := lst[i];
    if num < 0 then
      res[i] := 0
    else if num = 0 then
      res[i] := 1
    else
      res[i] := Round(Power(num, pow));
  end;
  Result := res;
end;

function KnapSackSolution(values, weights: array of integer; capacity: integer): integer;
begin
  var dp := new integer[values.Length + 1, capacity + 1];

  for var i := 1 to values.Length do
    for var j := 0 to capacity do
      if weights[i - 1] > j then
        dp[i, j] := dp[i - 1, j]
      else
        dp[i, j] := Max(dp[i - 1, j], dp[i - 1, j - weights[i - 1]] + values[i - 1]);

  Result := dp[values.Length, capacity];
end;

function MaxNumByFlipping(num: integer): integer;
begin
  if num = 9999 then
  begin
    Result := num;
    exit;
  end;

  var numStr := num.ToString.ToCharArray;
  for var i := 0 to numStr.Length - 1 do
  begin
    if numStr[i] = '9' then
      continue
    else if numStr[i] = '6' then
    begin
      numStr[i] := '9';
      break;
    end;
  end;

  Result := StrToInt(string.Join('', numStr));
end;

function UniqueElementCount(lst: array of integer): integer;
begin
  Result := lst.Distinct.Count;
end;

function FindSmallestRepeatingSubseq(s: string): string;
begin
  for var i := 1 to s.Length div 2 do
  begin
    var subseq := s.Substring(0, i);
    var repeated := '';
    for var j := 1 to s.Length div i do
      repeated += subseq;
    if repeated + subseq.Substring(0, s.Length mod i) = s then
    begin
      Result := subseq;
      exit;
    end;
  end;
  Result := s;
end;

function FindMaxSumSubarray(arr: array of integer; k: integer): integer;
begin
  if (arr.Length = 0) or (k <= 0) or (k > arr.Length) then
  begin
    Result := 0;
    exit;
  end;

  var windowSum := 0;
  for var i := 0 to k - 1 do
    windowSum += arr[i];

  var maxSum := windowSum;

  for var i := 0 to arr.Length - k - 1 do
  begin
    windowSum := windowSum - arr[i] + arr[i + k];
    maxSum := Max(maxSum, windowSum);
  end;

  Result := maxSum;
end;

function FindSmallestSubarray(arr: array of integer; targetSum: integer): integer;
begin
  var windowSum := 0;
  var windowStart := 0;
  var minLength := integer.MaxValue;

  for var windowEnd := 0 to arr.Length - 1 do
  begin
    windowSum += arr[windowEnd];

    while windowSum >= targetSum do
    begin
      minLength := Min(minLength, windowEnd - windowStart + 1);
      windowSum -= arr[windowStart];
      windowStart += 1;
    end;
  end;

  if minLength <> integer.MaxValue then
    Result := minLength
  else
    Result := 0;
end;

function HeapMaxMin(lst: array of integer): (integer, integer);
begin
  var heap := new List<integer>(lst);
  var maxHeap := new List<integer>(lst);

  heap.Sort;
  maxHeap.Sort((x, y) -> y.CompareTo(x));

  Result := (maxHeap[0], heap[0]);
end;

function FindRepetition(A: array of integer; x: integer): integer;

  function FindFirstOccurrence(arr: array of integer; target: integer): integer;
  begin
    var left := 0;
    var right := arr.Length - 1;
    var resultIndex := -1;

    while left <= right do
    begin
      var mid := (left + right) div 2;
      if target = arr[mid] then
      begin
        resultIndex := mid;
        right := mid - 1;
      end
      else if target < arr[mid] then
        right := mid - 1
      else
        left := mid + 1;
    end;
    Result := resultIndex;
  end;

  function FindLastOccurrence(arr: array of integer; target: integer): integer;
  begin
    var left := 0;
    var right := arr.Length - 1;
    var resultIndex := -1;

    while left <= right do
    begin
      var mid := (left + right) div 2;
      if target = arr[mid] then
      begin
        resultIndex := mid;
        left := mid + 1;
      end
      else if target < arr[mid] then
        right := mid - 1
      else
        left := mid + 1;
    end;
    Result := resultIndex;
  end;

begin
  var first := FindFirstOccurrence(A, x);
  if first = -1 then
  begin
    Result := 0;
    exit;
  end;

  var last := FindLastOccurrence(A, x);
  Result := last - first + 1;
end;

function MultiplyIndex(lst: array of integer): array of integer;
begin
  Result := new integer[lst.Length];
  for var i := 0 to lst.Length - 1 do
    Result[i] := i * lst[i];
end;

function SquareOrAbsolute(numbers: array of integer): array of integer;
begin
  Result := new integer[numbers.Length];
  for var i := 0 to numbers.Length - 1 do
  begin
    var num := numbers[i];
    if num >= 0 then
      Result[i] := num * num
    else
      Result[i] := Abs(num);
  end;
end;

function Distance3D(point1, point2: (integer, integer, integer)): real;
begin
  var (x1, y1, z1) := point1;
  var (x2, y2, z2) := point2;
  Result := Sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1) + (z2 - z1) * (z2 - z1));
end;

function RearrangeStrings(words: array of string): array of string;
begin
  var anagrams := new Dictionary<string, List<string>>;

  foreach var word in words do
  begin
    var sortedWord := string.Join('', word.ToCharArray.Sorted);
    if anagrams.ContainsKey(sortedWord) then
      anagrams[sortedWord].Add(word)
    else
      anagrams.Add(sortedWord, new List<string>([word]));
  end;

  var res := new List<string>;
  foreach var pair in anagrams do
    if pair.Value.Count > 1 then
      res.AddRange(pair.Value);

  Result := res.ToArray;
end;

function LargestPowerDividingFactorial(p, n: integer): integer;
begin
  var count := 0;
  var i := p;
  while i <= n do
  begin
    count += n div i;
    i *= p;
  end;
  Result := count;
end;

function NumWays(n: integer): integer;
begin
  if n < 0 then
    Result := 0
  else if n = 0 then
    Result := 1
  else
    Result := NumWays(n - 1) + NumWays(n - 3) + NumWays(n - 4);
end;

function CheckStrongNumber(num: integer): boolean;

  function Factorial(n: integer): integer;
  begin
    if (n = 0) or (n = 1) then
      Result := 1
    else
      Result := n * Factorial(n - 1);
  end;

begin
  var temp := num;
  var sum := 0;
  while num > 0 do
  begin
    var digit := num mod 10;
    sum += Factorial(digit);
    num := num div 10;
  end;
  Result := sum = temp;
end;

function MinMovesEqualElements(nums: array of integer): integer;
begin
  var minNum := nums.Min;
  var moves := 0;
  foreach var num in nums do
    moves += num - minNum;
  Result := moves;
end;

function MaxAbs(numbers: array of integer): integer;
begin
  Result := numbers.Max(x -> Abs(x));
end;

type
  TreeNode = class
    val: integer;
    left, right: TreeNode;

    constructor Create(v: integer; l: TreeNode := nil; r: TreeNode := nil);
    begin
      val := v;
      left := l;
      right := r;
    end;
  end;

procedure InorderTraversal(root: TreeNode; var arr: List<integer>);
begin
  if root <> nil then
  begin
    InorderTraversal(root.left, arr);
    arr.Add(root.val);
    InorderTraversal(root.right, arr);
  end;
end;

function BuildBST(sortedArr: List<integer>; startIndex, endIndex: integer): TreeNode;
begin
  if startIndex > endIndex then
  begin
    Result := nil;
    exit;
  end;

  var mid := (startIndex + endIndex) div 2;
  Result := new TreeNode(sortedArr[mid]);
  Result.left := BuildBST(sortedArr, startIndex, mid - 1);
  Result.right := BuildBST(sortedArr, mid + 1, endIndex);
end;

function CreateBST(arr: array of integer): TreeNode;
begin
  if arr.Length = 0 then
  begin
    Result := nil;
    exit;
  end;

  var sortedArr := arr.ToList;
  sortedArr.Sort;
  Result := BuildBST(sortedArr, 0, sortedArr.Count - 1);
end;

function IntersectionOfTwoBST(tree1, tree2: array of integer): array of integer;
begin
  var bst1 := CreateBST(tree1);
  var bst2 := CreateBST(tree2);

  var arr1 := new List<integer>;
  var arr2 := new List<integer>;

  InorderTraversal(bst1, arr1);
  InorderTraversal(bst2, arr2);

  var i := 0;
  var j := 0;
  var res := new List<integer>;

  while (i < arr1.Count) and (j < arr2.Count) do
  begin
    if arr1[i] < arr2[j] then
      i += 1
    else if arr1[i] > arr2[j] then
      j += 1
    else
    begin
      res.Add(arr1[i]);
      i += 1;
      j += 1;
    end;
  end;

  Result := res.ToArray;
end;

function IsStraight(nums: array of integer): boolean;
begin
  if (nums.Length = 0) or (nums.Length <> 5) then
  begin
    Result := False;
    exit;
  end;

  var sortedNums := nums.ToList;
  sortedNums.Sort;
  var joker := 0;

  for var i := 0 to 3 do
  begin
    if sortedNums[i] = 0 then
      joker += 1
    else
    begin
      if sortedNums[i] = sortedNums[i + 1] then
      begin
        Result := False;
        exit;
      end;
    end;
  end;

  Result := sortedNums[4] - sortedNums[joker] < 5;
end;

function MaxSubArrayLength(twoDArray: array of array of integer): integer;
begin
  var maxLength := 0;
  foreach var subArray in twoDArray do
    if subArray.Length > maxLength then
      maxLength := subArray.Length;
  Result := maxLength;
end;

function CanFormSquareComb(a, b, c, d, i: integer; nums: array of integer; q: integer): boolean;
begin
    if i = nums.Length then
    begin
      Result := (a = q) and (b = q) and (c = q) and (d = q);
      exit;
    end;

    var sides := new integer[4];
    sides[0] := a;
    sides[1] := b;
    sides[2] := c;
    sides[3] := d;

    for var j := 0 to 3 do
    begin
      if sides[j] + nums[i] <= q then
      begin
        sides[j] += nums[i];
        if CanFormSquareComb(sides[0], sides[1], sides[2], sides[3], i + 1, nums, q) then
        begin
          Result := True;
          exit;
        end;
        sides[j] -= nums[i];
      end;
    end;
    Result := False;
end;

function CanFormSquare(nums: array of integer): boolean;
begin
  var S := nums.Sum;
  if S mod 4 <> 0 then
  begin
    Result := False;
    exit;
  end;

  var q := S div 4;
  var N := nums.Length;
  if N <= 3 then
  begin
    Result := False;
    exit;
  end;

  var sortedNums := nums.ToList;
  sortedNums.Sort;
  sortedNums.Reverse;

  Result := CanFormSquareComb(0, 0, 0, 0, 0, sortedNums.ToArray, q);
end;

