function ProductOfOtherElements(nums: array of integer): array of integer;
begin
  var length := nums.Length;
  var answer := new integer[length];
  for var i := 0 to length - 1 do
    answer[i] := 1;

  var left := 1;
  for var i := 0 to length - 1 do
  begin
    answer[i] *= left;
    left *= nums[i];
  end;

  var right := 1;
  for var i := length - 1 downto 0 do
  begin
    answer[i] *= right;
