  var longestWord := wordList[0];
  var hold := wordList[0];

  for var i := 1 to wordList.Count - 1 do
  begin
    if wordList[i].StartsWith(hold) then
    begin
      if wordList[i].Length >= longestWord.Length then
        longestWord := wordList[i];
      hold := wordList[i];
    end
    else
      hold := wordList[i];
  end;

  Result := longestWord;
end;

