function HighestPowerOfTwo(n: integer): integer;
begin
  var power := 0;
  while (1 shl power) <= n do
    power += 1;
  Result := power - 1;
end;

function SumLargestSubarray(arr: array of integer): integer;
begin
  var maxSoFar := arr[0];
  var currMax := arr[0];

  for var i := 1 to arr.Length - 1 do
  begin
    currMax := Max(arr[i], currMax + arr[i]);
    maxSoFar := Max(maxSoFar, currMax);
  end;

  Result := maxSoFar;
end;

function CountWaysToClimbStaircase(n: integer): integer;
begin
  if n <= 2 then
  begin
    Result := n;
    exit;
  end;

  var a := 1;
  var b := 2;

  for var i := 3 to n do
  begin
    var temp := a + b;
    a := b;
    b := temp;
  end;

  Result := b;
end;

