function SwapIndices(matrix: array [,] of integer): array [,] of integer;
begin
  var resultMatrix := new integer[matrix.GetLength(1), matrix.GetLength(0)];

  for var i := 0 to matrix.GetLength(0) - 1 do
    for var j := 0 to matrix.GetLength(1) - 1 do
      resultMatrix[j, i] := matrix[i, j];

  Result := resultMatrix;
end;

function CheckIntersection(rect1, rect2: (integer, integer, integer, integer)): boolean;
begin
  var (x1, y1, x2, y2) := rect1;
  var (x3, y3, x4, y4) := rect2;

  if (x1 > x4) or (x3 > x2) then
  begin
    Result := false;
    exit;
  end;

  if (y1 > y4) or (y3 > y2) then
  begin
    Result := false;
    exit;
  end;

  Result := true;
end;

function DoRectanglesOverlap(rect1, rect2: array of integer): boolean;
begin
  var x1 := rect1[0];
  var y1 := rect1[1];
  var x2 := rect1[2];
  var y2 := rect1[3];
  var x3 := rect2[0];
  var y3 := rect2[1];
  var x4 := rect2[2];
  var y4 := rect2[3];

  if (x3 > x2) or (x4 < x1) or (y3 > y2) or (y4 < y1) then
    Result := false
  else
    Result := true;
end;

function LongestEvenSubarray(nums: array of integer): integer;
begin
  var maxLen := 0;
  var currLen := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    if nums[i] mod 2 = 0 then
    begin
      currLen += 1;
      maxLen := Max(maxLen, currLen);
    end
    else
      currLen := 0;
  end;

  Result := maxLen;
end;

function FindUniqueSubstrings(s: string): integer;
begin
  var substrings := new HashSet<string>;

  for var i := 0 to s.Length - 1 do
    for var j := i + 1 to s.Length do
      substrings.Add(s.Substring(i, j - i));

  Result := substrings.Count;
end;

function RepeatedSubstring(s: string): boolean;
begin
  for var i := 1 to s.Length div 2 do
  begin
    if s.Length mod i = 0 then
    begin
      var substr := s.Substring(0, i);
      var repeated := '';

      for var j := 1 to s.Length div i do
        repeated += substr;

      if repeated = s then
      begin
        Result := true;
        exit;
      end;
    end;
  end;

  Result := false;
end;

function TransposedMatrix(matrix: array [,] of integer): array [,] of integer;
begin
  var resultMatrix := new integer[matrix.GetLength(1), matrix.GetLength(0)];

  for var i := 0 to matrix.GetLength(0) - 1 do
    for var j := 0 to matrix.GetLength(1) - 1 do
      resultMatrix[j, i] := matrix[i, j];

  Result := resultMatrix;
end;

function NthTribonacci(n: integer): integer;
begin
  if n = 1 then
  begin
    Result := 1;
    exit;
  end;

  if n = 2 then
  begin
    Result := 1;
    exit;
  end;

  if n = 3 then
  begin
    Result := 2;
    exit;
  end;

  var trib := new integer[n + 1];
  trib[1] := 1;
  trib[2] := 1;
  trib[3] := 2;
  var modVal := 1000000007;

  for var i := 4 to n do
    trib[i] := (trib[i - 1] mod modVal + trib[i - 2] mod modVal + trib[i - 3] mod modVal) mod modVal;

  Result := trib[n];
end;

