function NumWaysToTile(n: integer): integer;
begin
  if n = 0 then
  begin
    Result := 1;
    exit;
  end;

  if n = 1 then
  begin
    Result := 1;
    exit;
  end;

  var dp := new integer[n + 1];
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
    dp[i] := dp[i - 1] + dp[i - 2];

  Result := dp[n];
end;

