function NumOfBST(n: integer): integer;
begin
  if (n = 0) or (n = 1) then
  begin
    Result := 1;
    exit;
  end;

  var num := 0;
  for var i := 1 to n do
    num += NumOfBST(i - 1) * NumOfBST(n - i);

  Result := num;
end;

function FindMedianSortedLists(nums1, nums2: array of integer): real;
begin
  var nums := nums1.Concat(nums2).ToArray;
  &Array.Sort(nums);
  var length := nums.Length;

  if length mod 2 = 0 then
    Result := (nums[length div 2] + nums[length div 2 - 1]) / 2
  else
    Result := nums[length div 2];
end;

