function ReverseDict(testDict: Dictionary<string, integer>): Dictionary<integer, object>;
begin
  var reverse := new Dictionary<integer, List<string>>;

  foreach var pair in testDict do
  begin
    if not reverse.ContainsKey(pair.Value) then
      reverse[pair.Value] := new List<string>;
    reverse[pair.Value].Add(pair.Key);
  end;

  var res := new Dictionary<integer, object>;
  foreach var pair in reverse do
  begin
    if pair.Value.Count = 1 then
      res[pair.Key] := pair.Value[0]
    else
      res[pair.Key] := pair.Value;
  end;

  Result := res;
end;

