function MaxProductSubarray(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var minVal := nums[0];
  var maxVal := nums[0];
  var resultVal := nums[0];

  for var i := 1 to nums.Length - 1 do
  begin
    if nums[i] < 0 then
    begin
      var temp := minVal;
      minVal := maxVal;
      maxVal := temp;
    end;

    maxVal := Max(nums[i], maxVal * nums[i]);
    minVal := Min(nums[i], minVal * nums[i]);
    resultVal := Max(resultVal, maxVal);
  end;

  Result := resultVal;
end;

function DivideArray(arr: array of integer): boolean;
begin
  var total := arr.Sum;
  if total mod 2 <> 0 then
  begin
    Result := false;
    exit;
  end;

  var target := total div 2;
  var dp := new boolean[target + 1];
  dp[0] := true;

  for var i := 0 to arr.Length - 1 do
    for var j := target downto arr[i] do
      dp[j] := dp[j] or dp[j - arr[i]];

  Result := dp[target];
end;

function LongestBeautifulSubstring(word: string): integer;
begin
  var ret := 0;
  var res := 0;
  var kind := new HashSet<char>;

  for var i := 0 to word.Length - 1 do
  begin
    if i = 0 then
    begin
      res := 1;
      kind.Add(word[i]);
    end
    else
    begin
      if word[i] >= word[i - 1] then
      begin
        res += 1;
        kind.Add(word[i]);
        if kind.Count = 5 then
          ret := Max(ret, res);
      end
      else
      begin
        res := 1;
        kind.Clear;
        kind.Add(word[i]);
      end;
    end;
  end;

  Result := ret;
end;

function AlternateMerge(str1, str2: string): string;
begin
  var mergedStr := '';
  var i := 0;
  var j := 0;

  while (i < str1.Length) and (j < str2.Length) do
  begin
    mergedStr += str1[i] + str2[j];
    i += 1;
    j += 1;
  end;

  if i < str1.Length then
    mergedStr += str1.Substring(i);

  if j < str2.Length then
    mergedStr += str2.Substring(j);

  Result := mergedStr;
end;

