function FindLongestSubarray(arr: array of integer): integer;
begin
  var n := arr.Length;
  var sumVal := 0;
  var maxLen := 0;
  var m := new Dictionary<integer, integer>;

  for var i := 0 to n - 1 do
  begin
    if arr[i] = 0 then
      sumVal += -1
    else
      sumVal += 1;

    if sumVal = 0 then
      maxLen := i + 1;

    if m.ContainsKey(sumVal) then
      maxLen := Max(maxLen, i - m[sumVal])
    else
      m[sumVal] := i;
  end;

  Result := maxLen;
end;

function LongestCommonPrefix(strs: array of string): string;
begin
  if strs.Length = 0 then
  begin
    Result := '';
    exit;
  end;

  var shortest := strs.MinBy(s -> s.Length);

  for var i := 0 to shortest.Length - 1 do
    for var j := 0 to strs.Length - 1 do
      if strs[j][i] <> shortest[i] then
      begin
        Result := shortest.Substring(0, i);
        exit;
      end;

  Result := shortest;
end;

