uses System.Collections.Generic;

function IsAcyclic(numNodes: integer; edgesList: List<(integer, integer)>): boolean;
begin
  var graph := new Dictionary<integer, List<integer>>;
  var indegree := new integer[numNodes];

  for var i := 0 to numNodes - 1 do
    graph[i] := new List<integer>;

  foreach var edge in edgesList do
  begin
    graph[edge[0]].Add(edge[1]);
    indegree[edge[1]] += 1;
  end;

  var queue := new Queue<integer>;
  for var node := 0 to numNodes - 1 do
    if indegree[node] = 0 then
      queue.Enqueue(node);

  var visited := 0;

  while queue.Count > 0 do
  begin
    var node := queue.Dequeue;
    visited += 1;

    foreach var neighbor in graph[node] do
    begin
      indegree[neighbor] -= 1;
      if indegree[neighbor] = 0 then
        queue.Enqueue(neighbor);
    end;
  end;

  Result := visited = numNodes;
end;

function LeastBricks(wall: List<List<integer>>): integer;
begin
  var numRows := wall.Count;
  var minBricks := numRows;
  var edgesAt := new Dictionary<integer, integer>;
  var wallWidth := 0;

  if (wall[0].Count = 1) and (wall[0][0] = 1) then
  begin
    Result := numRows;
    exit;
  end;

  foreach var row in wall do
  begin
    var position := 0;
    for var i := 0 to row.Count - 2 do
    begin
      position += row[i];
      if not edgesAt.ContainsKey(position) then
        edgesAt[position] := 0;
      edgesAt[position] += 1;
    end;
    if wallWidth = 0 then
      wallWidth := position + row[row.Count - 1];
  end;

  foreach var position in edgesAt.Keys do
  begin
    if (position > 0) and (position < wallWidth) then
    begin
      var bricksCrossed := numRows - edgesAt[position];
      minBricks := Min(minBricks, bricksCrossed);
    end;
  end;

  Result := minBricks;
end;

function MinDelToMakeEqual(str1, str2: string): integer;
begin
  var m := str1.Length;
  var n := str2.Length;
  var dp := new integer[m + 1, n + 1];

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if str1[i] = str2[j] then
        dp[i + 1, j + 1] := dp[i, j] + 1
      else
        dp[i + 1, j + 1] := Max(dp[i + 1, j], dp[i, j + 1]);
    end;

  Result := m - dp[m, n] + n - dp[m, n];
end;

function RearrangeCharacters(s, target: string): integer;
begin
  var ans := integer.MaxValue;
  var cnt := new Dictionary<char, integer>;
  var targetCnt := new Dictionary<char, integer>;

  for var i := 0 to s.Length - 1 do
  begin
    if not cnt.ContainsKey(s[i]) then
      cnt[s[i]] := 0;
    cnt[s[i]] += 1;
  end;

  for var i := 0 to target.Length - 1 do
  begin
    if not targetCnt.ContainsKey(target[i]) then
      targetCnt[target[i]] := 0;
    targetCnt[target[i]] += 1;
  end;

  foreach var pair in targetCnt do
  begin
    if not cnt.ContainsKey(pair.Key) then
    begin
      Result := 0;
      exit;
    end;
    ans := Min(ans, cnt[pair.Key] div pair.Value);
  end;

  Result := ans;
end;

function ReverseOrPalindrome(s: string): string;
begin
  var reversedS := new string(s.Reverse.ToArray);
  if s = reversedS then
    Result := s
  else
    Result := reversedS;
end;

function KthSmallestString(nums: array of string; k: integer): string;
begin
  var trimmedStrings := nums.Select(s -> s.Substring(k)).ToArray;
  &Array.Sort(trimmedStrings);

  if trimmedStrings.Length > 0 then
    Result := trimmedStrings[0]
  else
    Result := '';
end;

function FindFirstOccurrence(nums: array of integer; target: integer; startIdx, endIdx: integer): integer;
begin
  var left := startIdx;
  var right := endIdx;
  while left < right do
  begin
    var mid := left + (right - left) div 2;
    if nums[mid] < target then
      left := mid + 1
    else
      right := mid;
  end;
  if nums[left] = target then
    Result := left
  else
    Result := -1;
end;

function FindLastOccurrence(nums: array of integer; target: integer; startIdx, endIdx: integer): integer;
begin
  var left := startIdx;
  var right := endIdx;
  while left < right do
  begin
    var mid := left + (right - left + 1) div 2;
    if nums[mid] > target then
      right := mid - 1
    else
      left := mid;
  end;
  if nums[right] = target then
    Result := right
  else
    Result := -1;
end;

function CountTargetOccurrences(nums: array of integer; target: integer): integer;
begin
  var firstOccurrence := FindFirstOccurrence(nums, target, 0, nums.Length - 1);
  if firstOccurrence = -1 then
  begin
    Result := 0;
    exit;
  end;

  var lastOccurrence := FindLastOccurrence(nums, target, firstOccurrence, nums.Length - 1);
  Result := lastOccurrence - firstOccurrence + 1;
end;

function ValidParenthesesSequences(n: integer): integer;
begin
  var catalan := new integer[n + 1];
  catalan[0] := 1;
  catalan[1] := 1;

  for var i := 2 to n do
    for var j := 0 to i - 1 do
      catalan[i] += catalan[j] * catalan[i - j - 1];

  Result := catalan[n];
end;

function SmallestMissingCoin(coins: array of integer): integer;
begin
  &Array.Sort(coins);
  var maxReachable := 0;

  for var i := 0 to coins.Length - 1 do
  begin
    if coins[i] > maxReachable + 1 then
      break;
    maxReachable += coins[i];
  end;

  Result := maxReachable + 1;
end;

uses System.Collections.Generic;

function ValidParenthesis(parenthesisList: array of string): boolean;
begin
  var stack := new Stack<string>;

  for var i := 0 to parenthesisList.Length - 1 do
  begin
    if parenthesisList[i] = '(' then
      stack.Push('(')
    else if parenthesisList[i] = ')' then
    begin
      if stack.Count > 0 then
        stack.Pop
      else
      begin
        Result := false;
        exit;
      end;
    end;
  end;

  Result := stack.Count = 0;
end;

function Factorial(memo: Dictionary<integer, integer>; n: integer): integer;
begin
  if n = 0 then
  begin
    Result := 1;
    exit;
  end;

  if memo.ContainsKey(n) then
    Result := memo[n]
    else
  begin
    var num := n * Factorial(memo, n - 1);
    memo[n] := num;
    Result := num;
  end;
end;

function FactorialMemo(n: integer): integer;
begin
  var memo := new Dictionary<integer, integer>;
  Result := Factorial(memo, n);
end;

function LongestSubarray(nums: array of integer): integer;
begin
  var left := 0;
  var zeroCount := 0;
  var maxLen := 0;

  for var right := 0 to nums.Length - 1 do
  begin
    if nums[right] = 0 then
      zeroCount += 1;

    while zeroCount > 1 do
    begin
      if nums[left] = 0 then
        zeroCount -= 1;
      left += 1;
    end;

    maxLen := Max(maxLen, right - left);
  end;

  Result := maxLen;
end;

function HasSubstrMatch(A, B: array of integer; k: integer): boolean;
begin
  if k = 0 then
  begin
    Result := true;
    exit;
  end;

  var hash2inds := new Dictionary<integer, List<integer>>;

  for var i := 0 to A.Length - k do
  begin
    var subA := A[i:i + k];
    var hash := subA.GetHashCode;

    if not hash2inds.ContainsKey(hash) then
      hash2inds[hash] := new List<integer>;
    hash2inds[hash].Add(i);
  end;

  for var j := 0 to B.Length - k do
  begin
    var subB := B[j:j + k];
    var hash := subB.GetHashCode;

    if hash2inds.ContainsKey(hash) then
    begin
      foreach var i in hash2inds[hash] do
        if A[i:i + k].SequenceEqual(subB) then
        begin
          Result := true;
          exit;
        end;
    end;
  end;

  Result := false;
end;

function FindMaxSubarrayLength(A, B: array of integer): integer;
begin
  var lo := 0;
  var hi := Min(A.Length, B.Length) + 1;

  while lo < hi do
  begin
    var k := (lo + hi) div 2;
    if HasSubstrMatch(A, B, k) then
      lo := k + 1
    else
      hi := k;
  end;

  Result := lo - 1;
end;

function LongestZigzag(nums: array of integer): integer;
begin
  if nums.Length < 2 then
  begin
    Result := nums.Length;
    exit;
  end;

  var up := new integer[nums.Length];
  var down := new integer[nums.Length];

  for var i := 0 to nums.Length - 1 do
  begin
    up[i] := 1;
    down[i] := 1;
  end;

  for var i := 1 to nums.Length - 1 do
  begin
    if nums[i] > nums[i - 1] then
      up[i] := down[i - 1] + 1
    else if nums[i] < nums[i - 1] then
      down[i] := up[i - 1] + 1;
  end;

  Result := Max(up.Max, down.Max);
end;

