function PerformOperation(num1, num2: integer; &operator: string): real;
begin
  case &operator of
    '+': Result := num1 + num2;
    '-': Result := num1 - num2;
    '*': Result := num1 * num2;
    '/': 
      if num2 <> 0 then
        Result := num1 / num2
      else
        raise new System.DivideByZeroException('Error: Division by zero');
    else
      raise new System.ArgumentException('Error: Invalid operator');
  end;
end;

