function IsPalindromeAnagram(s: string): boolean;
begin
  var charCounts := new Dictionary<char, integer>;

  for var i := 0 to s.Length - 1 do
  begin
    if not charCounts.ContainsKey(s[i]) then
      charCounts[s[i]] := 0;
    charCounts[s[i]] += 1;
  end;

  var oddCount := 0;
  foreach var count in charCounts.Values do
  begin
    if count mod 2 <> 0 then
      oddCount += 1;
    if oddCount > 1 then
    begin
      Result := false;
      exit;
    end;
  end;

  Result := true;
end;

function LongestSubstringWithoutRepeat(s: string): integer;
begin
  var charMap := new Dictionary<char, integer>;
  var left := 0;
  var resultVal := 0;

  for var right := 0 to s.Length - 1 do
  begin
    if charMap.ContainsKey(s[right]) then
      left := Max(left, charMap[s[right]] + 1);

    charMap[s[right]] := right;
    resultVal := Max(resultVal, right - left + 1);
  end;

  Result := resultVal;
end;

