function MinDifference(arr: array of integer): integer;
begin
  &Array.Sort(arr);
  var minDiff := integer.MaxValue;

  for var i := 1 to arr.Length - 1 do
  begin
    var diff := arr[i] - arr[i - 1];
    if diff < minDiff then
      minDiff := diff;
  end;

  Result := minDiff;
end;

function ReverseListInGroups(inputList: array of integer; k: integer): array of integer;
begin
  var output := new List<integer>;

  for var i := 0 to inputList.Length - 1 step k do
  begin
    var group := inputList[i:Min(i + k, inputList.Length)];
    &Array.Reverse(group);
    output.AddRange(group);
  end;

  Result := output.ToArray;
end;

function IsValid(row, col, R, C: integer): boolean;
begin
  Result := (row >= 0) and (row < R) and (col >= 0) and (col < C);
end;

function IsBorder(row, col, R, C: integer): boolean;
begin
  Result := (row = 0) or (row = R - 1) or (col = 0) or (col = C - 1);
end;

procedure BFS(grid: array of array of integer; row, col, R, C: integer; directions: array of (integer, integer));
begin
  grid[row, col] := 1;
  var queue := new Queue<(integer, integer)>;
  queue.Enqueue((row, col));

  while queue.Count > 0 do
  begin
    var (currR, currC) := queue.Dequeue;

    for var i := 0 to directions.Length - 1 do
    begin
      var (dr, dc) := directions[i];
      var nr := currR + dr;
      var nc := currC + dc;

      if IsValid(nr, nc, R, C) and (grid[nr, nc] = 0) then
      begin
        grid[nr, nc] := 1;
        queue.Enqueue((nr, nc));
      end;
    end;
  end;
end;

function ClosedIsland(grid: array of array of integer): integer;
begin
  var R := grid.Length;
  var C := grid[0].Length;
  var directions := Arr((1, 0), (0, 1), (-1, 0), (0, -1));

  for var row := 0 to R - 1 do
    for var col := 0 to C - 1 do
      if IsBorder(row, col, R, C) and (grid[row, col] = 0) then
        BFS(grid, row, col, R, C, directions);

  var res := 0;
  for var row := 0 to R - 1 do
    for var col := 0 to C - 1 do
      if grid[row, col] = 0 then
      begin
        BFS(grid, row, col, R, C, directions);
        res += 1;
      end;

  Result := res;
end;

function IsValidWordSquare(words: array of string): boolean;
begin
  if words.Length = 0 then
  begin
    Result := true;
    exit;
  end;

  var n := words.Length;
  for var i := 0 to n - 1 do
    for var j := 0 to words[i].Length - 1 do
      if (j >= n) or (i >= words[j].Length) or (words[i][j] <> words[j][i]) then
      begin
        Result := false;
        exit;
      end;

  Result := true;
end;

function IsMagicWordSquare(words: array of string): boolean;
begin
  if not IsValidWordSquare(words) then
  begin
    Result := false;
    exit;
  end;

  var n := words.Length;
  var rowSum := 0;
  for var i := 0 to words[0].Length - 1 do
    rowSum += Ord(words[0][i]) - Ord('a') + 1;

  for var i := 1 to n - 1 do
  begin
    var currentRowSum := 0;
    for var j := 0 to words[i].Length - 1 do
      currentRowSum += Ord(words[i][j]) - Ord('a') + 1;
    if currentRowSum <> rowSum then
    begin
      Result := false;
      exit;
    end;
  end;

  for var j := 0 to n - 1 do
  begin
    var colSum := 0;
    for var i := 0 to n - 1 do
      colSum += Ord(words[i][j]) - Ord('a') + 1;
    if colSum <> rowSum then
    begin
      Result := false;
      exit;
    end;
  end;

  Result := true;
end;

function NumDistinctSubsequences(s, t: string): integer;
begin
  var dp := new integer[t.Length + 1];
  dp[0] := 1;
  var sPtr := 0;

  while sPtr < s.Length do
  begin
    for var tPtr := t.Length - 1 downto 0 do
    begin
      if s[sPtr] = t[tPtr] then
        dp[tPtr + 1] += dp[tPtr];
    end;
    sPtr += 1;
  end;

  Result := dp[t.Length];
end;

function ModeNumber(listNums: array of string): string;
begin
  var occurrenceCount := new Dictionary<string, integer>;

  for var i := 0 to listNums.Length - 1 do
  begin
    if not occurrenceCount.ContainsKey(listNums[i]) then
      occurrenceCount[listNums[i]] := 0;
    occurrenceCount[listNums[i]] += 1;
  end;

  var maxCount := occurrenceCount.Values.Max;
  var mostCommon := occurrenceCount.First(pair -> pair.Value = maxCount).Key;

  Result := mostCommon;
end;

function Check234Pattern(nums: array of integer): boolean;
begin
  var deq := new Stack<integer>;
  var num2 := -1;

  for var i := nums.Length - 1 downto 0 do
  begin
    if (num2 <> -1) and (nums[i] < num2) then
    begin
      Result := true;
      exit;
    end;

    while (deq.Count > 0) and (deq.Peek < nums[i]) do
      num2 := deq.Pop;

    deq.Push(nums[i]);
  end;

  Result := false;
end;

function ProductOfDigits(n: integer): integer;
begin
  var product := 1;
  while n > 0 do
  begin
    product := product * (n mod 10);
    n := n div 10;
    if product = 0 then
    begin
      Result := 0;
      exit;
    end;
  end;
  Result := product;
end;

