end;

function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
  begin
    Result := false;
    exit;
  end;

  if n = 2 then
  begin
    Result := true;
    exit;
  end;

  if n mod 2 = 0 then
  begin
    Result := false;
    exit;
  end;

  var i := 3;
  while i * i <= n do
  begin
    if n mod i = 0 then
    begin
      Result := false;
      exit;
    end;
    i += 2;
  end;

  Result := true;
end;

function IsPrimeRandom(minVal, maxVal: integer): integer;
