function IsCurrIndexTurbulent(arr: array of integer; k: integer): boolean;
begin
  Result := ((arr[k] > arr[k - 1]) and (arr[k] > arr[k + 1])) or
            ((arr[k] < arr[k - 1]) and (arr[k] < arr[k + 1]));
end;

function MaxTurbulenceSize(arr: array of integer): integer;
begin
  if arr.Length < 2 then
  begin
    Result := arr.Length;
    exit;
  end;

  var maximum := 1;
  var startIdx := 0;
  var &end := 0;
  var N := arr.Length;

  while startIdx + 1 < N do
  begin
    if arr[startIdx] = arr[startIdx + 1] then
    begin
      startIdx += 1;
      continue;
    end;

    &end := startIdx + 1;
    while (&end + 1 < N) and IsCurrIndexTurbulent(arr, &end) do
      &end += 1;

    maximum := Max(maximum, &end - startIdx + 1);
    startIdx := &end;
  end;

  Result := maximum;
end;

function GetBadCharacterShift(pattern: string): Dictionary<char, integer>;
begin
  var badCharShift := new Dictionary<char, integer>;
  for var i := 0 to pattern.Length - 2 do
    badCharShift[pattern[i]] := pattern.Length - i - 1;
  Result := badCharShift;
end;

function BoyerMooreSearch(text, pattern: string): integer;
begin
  var textLength := text.Length;
  var patternLength := pattern.Length;

  if patternLength > textLength then
  begin
    Result := -1;
    exit;
  end;

  var badCharShift := GetBadCharacterShift(pattern);
  var i := patternLength - 1;

  while i < textLength do
  begin
    var j := patternLength - 1;
    var k := i;

    while (j >= 0) and (text[k] = pattern[j]) do
    begin
      k -= 1;
      j -= 1;
    end;

    if j = -1 then
    begin
      Result := k + 1;
      exit;
    end
    else
    begin
      var offset := patternLength;
      if badCharShift.ContainsKey(text[i]) then
        offset := badCharShift[text[i]];
      i += offset;
    end;
  end;

  Result := -1;
end;

function FindLongestHarmoniousSubsequence(nums: array of integer): integer;
begin
  var counts := new Dictionary<integer, integer>;

  for var i := 0 to nums.Length - 1 do
  begin
    if not counts.ContainsKey(nums[i]) then
      counts[nums[i]] := 0;
    counts[nums[i]] += 1;
  end;

  var lengthVal := 0;
  foreach var c in counts.Keys do
  begin
    if counts.ContainsKey(c + 1) then
      lengthVal := Max(lengthVal, counts[c] + counts[c + 1]);
  end;

  Result := lengthVal;
end;

function GetMaxRepetitions(s1: string; n1: integer; s2: string; n2: integer): integer;
begin
  var countS1 := new Dictionary<char, integer>;
  var countS2 := new Dictionary<char, integer>;

  for var i := 0 to s1.Length - 1 do
  begin
    if not countS1.ContainsKey(s1[i]) then
      countS1[s1[i]] := 0;
    countS1[s1[i]] += 1;
  end;

  for var i := 0 to s2.Length - 1 do
  begin
    if not countS2.ContainsKey(s2[i]) then
      countS2[s2[i]] := 0;
    countS2[s2[i]] += 1;
  end;

  foreach var ch in countS2.Keys do
    if not countS1.ContainsKey(ch) then
    begin
      Result := 0;
      exit;
    end;

  var l1 := s1.Length;
  var l2 := s2.Length;
  var i1 := 0;
  var i2 := 0;
  var total := l1 * n1;
  var dic := new Dictionary<(integer, integer), (integer, integer)>;

  while i1 < total do
  begin
    if s1[i1 mod l1] = s2[i2 mod l2] then
    begin
      var key := (i1 mod l1, i2 mod l2);
      if dic.ContainsKey(key) then
      begin
        var (prev1, prev2) := dic[key];
        var cir1 := i1 - prev1;
        var cir2 := i2 - prev2;
        var countCir1 := (total - i1) div cir1;
        i1 += countCir1 * cir1;
        i2 += countCir1 * cir2;
        if i1 >= total then break;
      end
      else
        dic[key] := (i1, i2);
      i2 += 1;
    end;
    i1 += 1;
  end;

  Result := i2 div (l2 * n2);
end;

uses System.Collections.Generic;

function ValidParenthesesSequence(s: string): boolean;
begin
  var mapping := new Dictionary<char, char>;
  mapping[')'] := '(';
  mapping[']'] := '[';
  mapping['}'] := '{';

  var stack := new Stack<char>;

  for var i := 0 to s.Length - 1 do
  begin
    if mapping.ContainsValue(s[i]) then
      stack.Push(s[i])
    else if mapping.ContainsKey(s[i]) then
    begin
      if (stack.Count = 0) or (mapping[s[i]] <> stack.Pop) then
      begin
        Result := false;
        exit;
      end;
    end
    else
    begin
      Result := false;
      exit;
    end;
  end;

  Result := stack.Count = 0;
end;

function CountPairsSum(arr: array of integer; targetSum: integer): integer;
begin
  var count := 0;
  var freq := new Dictionary<integer, integer>;

  for var i := 0 to arr.Length - 1 do
  begin
    var complement := targetSum - arr[i];
    if freq.ContainsKey(complement) then
      count += freq[complement];

    if freq.ContainsKey(arr[i]) then
      freq[arr[i]] += 1
    else
      freq[arr[i]] := 1;
  end;

  Result := count;
end;

function Rotate2DArray(matrix: array [,] of integer): array [,] of integer;
begin
  if matrix.GetLength(0) = 0 then
  begin
    Result := new integer[0, 0];
    exit;
  end;

  var rotated := new integer[matrix.GetLength(1), matrix.GetLength(0)];

  for var i := 0 to matrix.GetLength(0) - 1 do
    for var j := 0 to matrix.GetLength(1) - 1 do
      rotated[j, matrix.GetLength(0) - 1 - i] := matrix[i, j];

  Result := rotated;
end;

function ValidPermutation(A: array of integer): boolean;
begin
  var size := A.Length;
  if size < 1 then
  begin
    Result := false;
    exit;
  end;

  for var i := 1 to size do
    if not A.Contains(i) then
    begin
      Result := false;
      exit;
    end;

  Result := true;
end;

function WeightedAverage(numbers, weights: array of real): real;
begin
  if numbers.Length <> weights.Length then
  begin
    Result := 0;
    exit;
  end;

  var weightedSum := 0.0;
  var weightSum := 0.0;

  for var i := 0 to numbers.Length - 1 do
  begin
    weightedSum += numbers[i] * weights[i];
    weightSum += weights[i];
  end;

  Result := weightedSum / weightSum;
end;

function MostWordsFound(sentences: array of string): integer;
begin
  var count1 := new List<integer>;

  for var i := 0 to sentences.Length - 1 do
  begin
    var a := sentences[i].Split(' ');
    var b := a.Length;
    count1.Add(b);
