  begin
    if arr[i] = 0 then
      count -= 1
    else
      count += 1;

    if countMap.ContainsKey(count) then
      maxLen := Max(maxLen, i - countMap[count])
    else
      countMap[count] := i;
  end;

  Result := maxLen;
end;

type
  ListNode = class
    val: integer;
    next: ListNode;

    constructor Create(x: integer);
    begin
      val := x;
      next := nil;
