function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
  begin
    Result := false;
    exit;
  end;

  if n <= 3 then
  begin
    Result := true;
    exit;
  end;

  if (n mod 2 = 0) or (n mod 3 = 0) then
  begin
    Result := false;
    exit;
  end;

  var i := 5;
  while i * i <= n do
  begin
    if (n mod i = 0) or (n mod (i + 2) = 0) then
    begin
      Result := false;
      exit;
    end;
    i += 6;
  end;

  Result := true;
end;

