function CalculateDeletions(str1, str2: string): integer;
begin
  var counter1 := new Dictionary<char, integer>;
  var counter2 := new Dictionary<char, integer>;

  for var i := 0 to str1.Length - 1 do
  begin
    if not counter1.ContainsKey(str1[i]) then
      counter1[str1[i]] := 0;
    counter1[str1[i]] += 1;
  end;

  for var i := 0 to str2.Length - 1 do
  begin
    if not counter2.ContainsKey(str2[i]) then
      counter2[str2[i]] := 0;
    counter2[str2[i]] += 1;
  end;

  var totalDeletions := 0;

  foreach var pair in counter1 do
  begin
    var char := pair.Key;
    if counter2.ContainsKey(char) then
      totalDeletions += Abs(pair.Value - counter2[char])
    else
      totalDeletions += pair.Value;
  end;

  foreach var pair in counter2 do
  begin
    var char := pair.Key;
    if not counter1.ContainsKey(char) then
      totalDeletions += pair.Value;
  end;

  Result := totalDeletions;
end;

function FindMaxSum(lst: List<List<integer>>): List<integer>;
begin
  var sums := new integer[lst.Count];

  for var i := 0 to lst.Count - 1 do
    sums[i] := lst[i].Sum;

  var index := 0;
  for var i := 1 to sums.Length - 1 do
    if sums[i] > sums[index] then
      index := i;

  Result := lst[index];
end;

function CountBalanced(s: string): integer;
begin
  var countR := 0;
  var countL := 0;
  var countOut := 0;

  for var i := 0 to s.Length - 1 do
  begin
    if s[i] = 'R' then
      countR += 1
    else if s[i] = 'L' then
      countL += 1;

    if countR = countL then
      countOut += 1;
