function ChampernowneDigit(n: integer): integer;
begin
  if n < 10 then
  begin
    Result := n;
    exit;
  end;

  var digit := 1;
  var total := 9;

  while n > total do
  begin
    n -= total;
    digit += 1;
    total := 9 * Round(Power(10, digit - 1)) * digit;
  end;

  var quotient := (n - 1) div digit;
  var remainder := (n - 1) mod digit;
  var number := Round(Power(10, digit - 1)) + quotient;

  Result := StrToInt(number.ToString[remainder]);
end;

function SquareRoots(nList: array of integer): array of integer;
begin
  var resultList := new List<integer>;

  for var i := 0 to nList.Length - 1 do
    resultList.Add(Round(Sqrt(nList[i])));

  Result := resultList.ToArray;
