    exit;
  end;

  var minHeap := new SortedSet<integer>(nums);
  var resultList := new List<integer>;

  for var i := 1 to k do
  begin
    resultList.Add(minHeap.Min);
    minHeap.Remove(minHeap.Min);
  end;

  Result := resultList.ToArray;
end;

