  var odd := 0;
  var foundEven := false;
  var foundOdd := false;

  for var i := 0 to lst.Length - 1 do
  begin
    if (not foundEven) and (lst[i] mod 2 = 0) then
    begin
      even := lst[i];
      foundEven := true;
    end
    else if (not foundOdd) and (lst[i] mod 2 <> 0) then
    begin
      odd := lst[i];
      foundOdd := true;
    end;

    if foundEven and foundOdd then
      break;
  end;

  if foundEven and foundOdd then
    Result := even * odd
  else
    Result := 0;
end;

