  var visited := ArrFill(n, False);
  var circles := 0;

  for var i := 0 to n - 1 do
    if not visited[i] then
    begin
      BFS(isConnected, i, visited);
      circles += 1;
    end;

  Result := circles;
end;

function IsPrimeNum(n: integer): boolean;
begin
  if n <= 1 then
    Result := False
  else
  begin
    for var i := 2 to Round(Sqrt(n)) do
      if n mod i = 0 then
      begin
        Result := False;
        exit;
      end;
    Result := True;
  end;
end;

function FindSecondSmallestPrime(numbers: List<integer>): integer;
