function StepWays(n: integer): integer;
begin
  if n <= 1 then
    Result := 1
  else
  begin
    var dp := ArrFill(n + 1, 0);
    dp[0] := 1;
    dp[1] := 1;
    for var i := 2 to n do
      dp[i] := dp[i - 1] + dp[i - 2];
    Result := dp[n];
  end;
end;

function MinAbsDiff(arr: List<integer>): integer;
begin
  arr.Sort;
  var minDiff := integer.MaxValue;

  for var i := 0 to arr.Count - 2 do
  begin
    var diff := Abs(arr[i] - arr[i + 1]);
    if diff < minDiff then
      minDiff := diff;
  end;

  Result := minDiff;
end;

function FindMaxCrossingSubarray(arr: List<integer>; low, mid, high: integer): integer;
begin
  var leftSum := integer.MinValue;
  var sumValue := 0;
  var maxLeft := mid;

  for var i := mid downto low do
  begin
    sumValue := sumValue + arr[i];
    if sumValue > leftSum then
    begin
      leftSum := sumValue;
      maxLeft := i;
    end;
  end;

  var rightSum := integer.MinValue;
  sumValue := 0;
  var maxRight := mid + 1;

  for var j := mid + 1 to high do
  begin
    sumValue := sumValue + arr[j];
    if sumValue > rightSum then
    begin
      rightSum := sumValue;
      maxRight := j;
    end;
  end;

  Result := leftSum + rightSum;
end;

