    res := res or (n and 1);
    n := n shr 1;
  end;
  Result := res;
end;

function MergeSortedLists(list1, list2: List<integer>): List<integer>;
begin
  var res := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < list1.Count) and (j < list2.Count) do
  begin
    if list1[i] < list2[j] then
    begin
      res.Add(list1[i]);
      i := i + 1;
    end
    else
    begin
      res.Add(list2[j]);
      j := j + 1;
    end;
  end;

  while i < list1.Count do
  begin
    res.Add(list1[i]);
    i := i + 1;
  end;

  while j < list2.Count do
  begin
    res.Add(list2[j]);
    j := j + 1;
  end;

  Result := res;
end;

function QuicksortRandomPivot(numbers: List<integer>): List<integer>;
begin
  if numbers.Count <= 1 then
    Result := numbers
  else
  begin
    var pivot := numbers[&System.Random.Create.Next(numbers.Count)];
    var less := new List<integer>;
    var equal := new List<integer>;
    var greater := new List<integer>;

    foreach var i in numbers do
      if i < pivot then
        less.Add(i)
      else if i = pivot then
        equal.Add(i)
      else
        greater.Add(i);

    Result := QuicksortRandomPivot(less).Concat(equal).Concat(QuicksortRandomPivot(greater)).ToList;
  end;
end;

