      vowelCount := vowelCount + 1
    else if char.IsLetter then
      consonantCount := consonantCount + 1;
  end;

  Result := (vowelCount, consonantCount);
end;

function FindUnion(arr1, arr2: List<integer>): List<integer>;
begin
  var union := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < arr1.Count) and (j < arr2.Count) do
  begin
    if arr1[i] < arr2[j] then
    begin
      union.Add(arr1[i]);
      i := i + 1;
    end
    else if arr2[j] < arr1[i] then
    begin
      union.Add(arr2[j]);
      j := j + 1;
    end
    else
    begin
      union.Add(arr2[j]);
      i := i + 1;
      j := j + 1;
    end;
  end;

  while i < arr1.Count do
  begin
    union.Add(arr1[i]);
    i := i + 1;
  end;

  while j < arr2.Count do
  begin
    union.Add(arr2[j]);
    j := j + 1;
  end;

  Result := union;
end;

type
  Node = class
    value: integer;
    left: Node;
    right: Node;

    constructor(v: integer; l: Node := nil; r: Node := nil);
    begin
      value := v;
      left := l;
      right := r;
    end;
  end;

function IsBinarySearchTree(node: Node; minValue: integer := integer.MinValue; maxValue: integer := integer.MaxValue): boolean;
begin
  if node = nil then
    Result := True
  else if (node.value < minValue) or (node.value > maxValue) then
    Result := False
  else
    Result := IsBinarySearchTree(node.left, minValue, node.value - 1) and
              IsBinarySearchTree(node.right, node.value + 1, maxValue);
end;

