  for var i := 1 to length div 2 do
  begin
    if length mod i = 0 then
    begin
      var pattern := s.Substring(0, i);
      var repeated := '';
      for var j := 1 to length div i do
        repeated := repeated + pattern;

      if repeated = s then
      begin
        Result := i;
        exit;
      end;
    end;
  end;
  Result := length;
end;

function ReverseSublist(lst: List<integer>; startIdx, endIdx: integer): List<integer>;
begin
  if startIdx >= endIdx then
    Result := lst
  else
  begin
    var sublist := lst.GetRange(startIdx, endIdx - startIdx + 1);
    sublist.Reverse;

    for var i := 0 to sublist.Count - 1 do
      lst[startIdx + i] := sublist[i];

    Result := lst;
  end;
end;

function IsPalindrome(s: string): boolean;
