  Result := resultList;
end;

function CountSameCharSubstrings(s: string): integer;
begin
  var count := 0;
  var i := 0;

  while i < s.Length do
  begin
    var j := i;
    while (j < s.Length) and (s[j] = s[i]) do
      j := j + 1;

    var length := j - i;
    count := count + (length * (length + 1)) div 2;
    i := j;
  end;

  Result := count;
end;

function RotateMatrix(mat: List<List<integer>>): List<List<integer>>;
begin
  var n := mat.Count;
  var res := new List<List<integer>>;

  for var i := 0 to n - 1 do
  begin
    res.Add(new List<integer>);
    for var j := 0 to n - 1 do
      res[i].Add(0);
  end;

  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      res[j][n - 1 - i] := mat[i][j];

  Result := res;
end;

function FindLongestPrefix(strs: List<string>): string;
begin
  if strs.Count = 0 then
    Result := ''
  else
  begin
    var shortest := strs.OrderBy(s -> s.Length).First;

    for var i := 0 to shortest.Length - 1 do
    begin
      var currentChar := shortest[i];
      foreach var other in strs do
        if other[i] <> currentChar then
        begin
          Result := shortest.Substring(0, i);
          exit;
        end;
    end;

    Result := shortest;
  end;
end;

function RemoveKDigits(num: string; k: integer): string;
begin
  var res := new List<char>;

  foreach var n in num do
  begin
    while (res.Count > 0) and (k > 0) and (res[res.Count - 1] > n) do
    begin
      res.RemoveAt(res.Count - 1);
      k := k - 1;
    end;
    res.Add(n);
  end;

  while k > 0 do
  begin
    res.RemoveAt(res.Count - 1);
    k := k - 1;
  end;

  var resultStr := string.Join('', res).TrimStart('0');
  if resultStr = '' then
    Result := '0'
  else
    Result := resultStr;
end;

