    if not mydict.ContainsKey(len) then
      mydict.Add(len, new List<string>);
    mydict[len].Add(strval);

    val := val * 2;
  end;

  var strn := n.ToString;
  if mydict.ContainsKey(strn.Length) then
    foreach var each in mydict[strn.Length] do
    begin
      var tmp1 := string.Join('', each.ToCharArray.Order.ToArray);
      var tmp2 := string.Join('', strn.ToCharArray.Order.ToArray);
      if tmp2 = tmp1 then
      begin
