function LengthOfLongstring(s: string): integer;
begin
  var charMap := new Dictionary<char, integer>;
  var left := 0;
  var maxLength := 0;

  for var right := 0 to s.Length - 1 do
  begin
    if charMap.ContainsKey(s[right]) then
      left := Max(left, charMap[s[right]] + 1);

    charMap[s[right]] := right;
    maxLength := Max(maxLength, right - left + 1);
  end;

  Result := maxLength;
end;

