    var mid := (low + high) div 2;

    if arr[mid] = target then
    begin
      resultIndex := mid;
      high := mid - 1;
    end
    else if arr[mid] > target then
      high := mid - 1
    else
      low := mid + 1;
  end;

  Result := resultIndex;
end;

