    Result := False;

  for var i := 0 to peakIndex - 1 do
    if arr[i] >= arr[i + 1] then
      Result := False;

  for var i := peakIndex to arr.Length - 2 do
    if arr[i] <= arr[i + 1] then
      Result := False;

  Result := True;
end;

