  while left < right do
  begin
    var temp := s[left];
    s[left] := s[right];
    s[right] := temp;
    left += 1;
    right -= 1;
  end;
  Result := s;
end;

function KadaneAlgorithm(arr: array of integer): integer;
begin
  var maxCurrent := arr[0];
  var maxGlobal := arr[0];
  for var i := 1 to arr.Length - 1 do
  begin
    maxCurrent := Max(arr[i], maxCurrent + arr[i]);
    if maxCurrent > maxGlobal then
      maxGlobal := maxCurrent;
  end;
  Result := maxGlobal;
end;

function MergeTwoLists(l1: array of integer; l2: array of integer): array of integer;
begin
  var l3 := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < l1.Length) and (j < l2.Length) do
  begin
    if l1[i] < l2[j] then
    begin
      l3.Add(l1[i]);
      i += 1;
    end
    else
    begin
      l3.Add(l2[j]);
      j += 1;
    end;
  end;

  if i = l1.Length then
    l3.AddRange(l2[j:l2.Length])
  else
    l3.AddRange(l1[i:l1.Length]);

  Result := l3.ToArray();
end;

