function FindSmallestSetOfVertices(n: integer; edges: array of (integer, integer)): array of integer;
begin
  var graph := new Dictionary<integer, List<integer>>;
  foreach var (start, dest) in edges do
  begin
    if not graph.ContainsKey(start) then
      graph[start] := new List<integer>;
    graph[start].Add(dest);
  end;

  var ans := new List<integer>;
  var values := new HashSet<integer>;
  foreach var valList in graph.Values do
    values.UnionWith(valList);

  for var i := 0 to n - 1 do
    if not values.Contains(i) then
      ans.Add(i);

  Result := ans.ToArray();
end;

function ScoreOfParentheses(s: string): integer;
begin
  var stackCount := 0;
  var start := 1;
  var score := 0;
  for var endIdx := 1 to s.Length do
  begin
    if s[endIdx] = '(' then
      stackCount += 1
    else if stackCount > 0 then
      stackCount -= 1;

    if stackCount = 0 then
    begin
      if endIdx - start = 1 then
        score += 1
      else
        score += 2 * ScoreOfParentheses(s.Substring(start, endIdx - start));
      start := endIdx + 1;
    end;
  end;
  Result := score;
end;

