function RightAngleTriangle(points: array of (real, real)): boolean;

  function IsRightAngleTriangle(p1: (real, real); p2: (real, real); p3: (real, real)): boolean;
  begin
    var (x1, y1) := p1;
    var (x2, y2) := p2;
    var (x3, y3) := p3;

    var dx1 := x2 - x1;
    var dy1 := y2 - y1;
    var dx2 := x3 - x1;
    var dy2 := y3 - y1;
    var dx3 := x3 - x2;
    var dy3 := y3 - y2;

    if (dx1 * dx2 + dy1 * dy2 = 0) or 
       (dx1 * dx3 + dy1 * dy3 = 0) or 
       (dx2 * dx3 + dy2 * dy3 = 0) then
      Result := True
    else
      Result := False;
  end;

begin
  for var i := 0 to points.Length - 1 do
    for var j := i + 1 to points.Length - 1 do
      for var k := j + 1 to points.Length - 1 do
        if IsRightAngleTriangle(points[i], points[j], points[k]) then
        begin
          Result := True;
          exit;
        end;
  Result := False;
end;

function FindConnectedComponents(matrix: array[,] of integer): integer;

  procedure Dfs(node: integer; var visited: array of boolean);
  begin
    visited[node] := True;
    for var neighbor := 0 to matrix.GetLength(0) - 1 do
      if (matrix[node, neighbor] = 1) and (not visited[neighbor]) then
        Dfs(neighbor, visited);
  end;

begin
  var n := matrix.GetLength(0);
  var visited := ArrFill(n, False);
  var components := 0;

  for var i := 0 to n - 1 do
    if not visited[i] then
    begin
      Dfs(i, visited);
      components += 1;
    end;

  Result := components;
end;

