function KSizedSubsets(arr: array of integer; k: integer): array of array of integer;

  procedure Backtrack(start: integer; path: List<integer>; var res: List<array of integer>);
  begin
    if path.Count = k then
    begin
      res.Add(path.ToArray());
      exit;
    end;

    for var i := start to arr.Length - 1 do
    begin
      path.Add(arr[i]);
      Backtrack(i + 1, path, res);
      path.RemoveAt(path.Count - 1);
