      else
      begin
        Result := False;
        exit;
      end;
    end;
  end;
  Result := True;
end;

function IndexAddition(testTup1: array of (integer, integer); testTup2: array of (integer, integer)): array of (integer, integer);
begin
  var res := new List<(integer, integer)>;
  for var i := 0 to Min(testTup1.Length, testTup2.Length) - 1 do
  begin
    var (a1, b1) := testTup1[i];
    var (a2, b2) := testTup2[i];
    res.Add((a1 + a2, b1 + b2));
