    exit;
  end;
  for var i := length downto 1 do
  begin
    if s[i] <> ' ' then
    begin
      for var x := i downto 1 do
      begin
        if s[x] = ' ' then
        begin
          Result := i - x;
          exit;
        end;
      end;
      Result := i;
      exit;
    end;
  end;
  Result := 0;
end;

