function FindDigitCount(num: integer): integer;
begin
  if num < 10 then
  begin
    Result := -1;
    exit;
  end;
  var rightmost := num mod 10;
  var count := 0;
  num := num div 10;
  while num > 0 do
  begin
    count += 1;
    var currentDigit := num mod 10;
    if currentDigit > rightmost then
    begin
      Result := count;
      exit;
    end;
    num := num div 10;
  end;
  Result := -1;
end;

function CanDecode(s: string): boolean;
begin
  var keypad := new Dictionary<integer, integer>;
  keypad[2] := 3;
  keypad[3] := 3;
  keypad[4] := 3;
  keypad[5] := 3;
  keypad[6] := 3;
  keypad[7] := 4;
  keypad[8] := 3;
  keypad[9] := 4;

  var n := s.Length;
  var dp := ArrFill(n + 1, False);
  dp[0] := True;

  for var i := 1 to n do
  begin
    for var j := 1 to Min(4, i) do
    begin
      if (i - j >= 0) and dp[i - j] then
      begin
        var substr := s.Substring(i - j, j);
        if substr.All(ch -> ch = substr[1]) and 
           (substr[1] in ['2'..'9']) and 
           (j <= keypad[StrToInt(substr[1])]) then
        begin
          dp[i] := True;
          break;
        end;
      end;
    end;
  end;

  Result := dp[n];
end;

function FindMinLength(gems: array of string): integer;
begin
  var gemTypes := new HashSet<string>(gems);
  var gemCount := new Dictionary<string, integer>;
  var start := 0;
  var minLength := integer.MaxValue;
  for var endIdx := 0 to gems.Length - 1 do
  begin
    if gemCount.ContainsKey(gems[endIdx]) then
      gemCount[gems[endIdx]] += 1
    else
      gemCount[gems[endIdx]] := 1;
    while gemCount.Count = gemTypes.Count do
    begin
      minLength := Min(minLength, endIdx - start + 1);
      gemCount[gems[start]] -= 1;
      if gemCount[gems[start]] = 0 then
        gemCount.Remove(gems[start]);
      start += 1;
    end;
  end;
  Result := if minLength <> integer.MaxValue then minLength else 0;
end;

function ConvertToDecimal(number: string; base: integer): integer;
begin
  var digits := '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  var answer := 0;
  for var i := 1 to number.Length do
  begin
    var pos := number.Length - i;
    var num := digits.IndexOf(number[i]);
    answer += num * Round(Power(base, pos));
  end;
  Result := answer;
end;

function FindSmallestUniqueSubstring(s: string): string;
begin
  var uniqueChars := new HashSet<char>(s);
  var types := uniqueChars.Count;
  var length := s.Length;
  var l := 1;
  var r := 1;
  var ansl := 1;
  var ansr := length;
  var current := new Dictionary<char, integer>;
  current[s[1]] := 1;

  while (l < length) and (r < length) do
  begin
    if current.Count < types then
    begin
      r += 1;
      if r > length then
        break;
      if current.ContainsKey(s[r]) then
        current[s[r]] += 1
      else
        current[s[r]] := 1;
    end
    else
    begin
      if (r - l) < (ansr - ansl) then
      begin
        ansl := l;
        ansr := r;
      end;
      current[s[l]] -= 1;
      if current[s[l]] = 0 then
        current.Remove(s[l]);
      l += 1;
    end;
  end;

  Result := s.Substring(ansl, ansr - ansl + 1);
end;

