function FindContinuousSubarrays(nums: array of integer; k: integer): integer;
begin
  var length := nums.Length;
  var ans := 0;
  var dic := new Dictionary<integer, integer>;
  dic[0] := 1;

  var currentSum := 0;
  for var i := 0 to length - 1 do
  begin
    currentSum += nums[i];
    var reminder := currentSum - k;
    if dic.ContainsKey(reminder) then
      ans += dic[reminder];

    if dic.ContainsKey(currentSum) then
      dic[currentSum] += 1
    else
      dic[currentSum] := 1;
  end;

  Result := ans;
end;

function CheckValidParentheses(s: string): boolean;
begin
  if s.Length mod 2 <> 0 then
    Result := false
  else
  begin
    var stack := new Stack<char>;
    for var i := 1 to s.Length do
    begin
      var ch := s[i];
      if ch = '(' then
        stack.Push(ch)
      else if ch = ')' then
      begin
        if stack.Count = 0 then
        begin
          Result := false;
          exit;
        end
        else
          stack.Pop;
      end;
    end;
    Result := stack.Count = 0;
  end;
end;

