function BinaryInsertionSort(arr: array of integer): array of integer;
begin
  var res := arr.ToArray;

  for var i := 1 to res.Length - 1 do
  begin
    var val := res[i];
    var left := 0;
    var right := i - 1;

    while left <= right do
    begin
      var mid := (left + right) div 2;
      if res[mid] > val then
        right := mid - 1
      else
        left := mid + 1;
    end;

    for var j := i - 1 downto left do
      res[j + 1] := res[j];

    res[left] := val;
  end;

  Result := res;
end;

function QuickSort(arr: array of integer): array of integer;
begin
  if arr.Length <= 1 then
  begin
    Result := arr;
    exit;
  end;

  var pivot := arr[arr.Length div 2];
  var left := new List<integer>;
  var middle := new List<integer>;
  var right := new List<integer>;

  for var i := 0 to arr.Length - 1 do
  begin
    if arr[i] < pivot then
      left.Add(arr[i])
    else if arr[i] = pivot then
      middle.Add(arr[i])
    else
      right.Add(arr[i]);
  end;

  Result := QuickSort(left.ToArray) + middle.ToArray + QuickSort(right.ToArray);
end;

function FindKthLargest(nums: array of integer; k: integer): integer;
begin
  if (nums.Length = 0) or (k <= 0) then
  begin
    Result := -1;
    exit;
  end;

  var heap := new List<integer>;

  for var i := 0 to nums.Length - 1 do
  begin
    heap.Add(nums[i]);

    if heap.Count > k then
    begin
      heap.Sort;
      heap.RemoveAt(0);
    end;
  end;

  heap.Sort;
  Result := heap[0];
end;

function SumIndexPrev(n: integer): array of integer;
begin
  if n = 1 then
  begin
    Result := new integer[1];
    Result[0] := 1;
    exit;
  end;

  var arr := new integer[n];
  arr[0] := 1;

  for var i := 1 to n - 1 do
  begin
    arr[i] := arr[i - 1] + i + 1;
  end;

  Result := arr;
end;

function SmallestDiff(arr: array of integer): integer;
begin
  var sortedArr := arr.ToArray;
  &Array.Sort(sortedArr);

  var minDiff := integer.MaxValue;
  for var i := 1 to sortedArr.Length - 1 do
  begin
    var diff := sortedArr[i] - sortedArr[i - 1];
    if diff < minDiff then
      minDiff := diff;
  end;

  Result := minDiff;
end;

function SumEvenProductOdd(nums: array of integer): (integer, integer);
begin
  var sumEven := 0;
  var productOdd := 1;
  var hasOdd := false;

  for var i := 0 to nums.Length - 1 do
  begin
    if nums[i] mod 2 = 0 then
      sumEven += nums[i]
    else
    begin
      productOdd *= nums[i];
      hasOdd := true;
    end;
  end;

  if not hasOdd then
    productOdd := 1;

  Result := (sumEven, productOdd);
end;

function SumLargestDigits(nums: array of integer): integer;
begin
  var maxNum := nums.Max;
  var maxNumStr := maxNum.ToString;
  var sum := 0;

  for var i := 1 to maxNumStr.Length do
  begin
    sum += StrToInt(maxNumStr[i]);
  end;

  Result := sum;
end;

function SmallerNumbersThanCurrent(nums: array of integer): array of integer;
begin
  var res := new integer[nums.Length];

  for var i := 0 to nums.Length - 1 do
  begin
    var count := 0;
    for var j := 0 to nums.Length - 1 do
    begin
      if (i <> j) and (nums[j] < nums[i]) then
        count += 1;
    end;
    res[i] := count;
  end;

  Result := res;
end;

function LargestDivisor(num: integer; divisors: array of integer): integer;
begin
  var sortedDivisors := divisors.ToArray;
  &Array.Sort(sortedDivisors);
  &Array.Reverse(sortedDivisors);

  for var i := 0 to sortedDivisors.Length - 1 do
  begin
    if num mod sortedDivisors[i] = 0 then
    begin
      Result := sortedDivisors[i];
      exit;
    end;
  end;

  Result := 1;
end;

function ConvertToISO(date: string): string;
begin
  var months := new Dictionary<string, string>;
  months['January'] := '01';
  months['February'] := '02';
  months['March'] := '03';
  months['April'] := '04';
  months['May'] := '05';
  months['June'] := '06';
  months['July'] := '07';
  months['August'] := '08';
  months['September'] := '09';
  months['October'] := '10';
  months['November'] := '11';
  months['December'] := '12';

  var parts := date.ToWords;
  if parts.Length <> 3 then
  begin
    Result := '';
    exit;
  end;

  var dayStr := parts[0];
  if dayStr.Length > 2 then
    dayStr := dayStr.Substring(1, dayStr.Length - 2);

  if dayStr.Length = 1 then
    dayStr := '0' + dayStr;

  var month := months[parts[1]];
  var year := parts[2];

  Result := year + '-' + month + '-' + dayStr;
end;

function SumOfAbs(lst: array of integer): integer;
begin
  var sum := 0;
  for var i := 0 to lst.Length - 1 do
  begin
    sum += Abs(lst[i]);
  end;
  Result := sum;
end;

type
  TreeNode = class
    val: integer;
    left, right: TreeNode;

    constructor Create(v: integer; l, r: TreeNode);
    begin
      val := v;
      left := l;
      right := r;
    end;
  end;

function FindLevel(root: TreeNode; k: integer): integer;
begin
  if root = nil then
  begin
    Result := 0;
    exit;
  end;

  if root.val = k then
  begin
    Result := 1;
    exit;
  end;

  var leftLevel := FindLevel(root.left, k);
  if leftLevel > 0 then
  begin
    Result := leftLevel + 1;
    exit;
  end;

  var rightLevel := FindLevel(root.right, k);
  if rightLevel > 0 then
  begin
    Result := rightLevel + 1;
    exit;
  end;

  Result := 0;
end;

function SquareOdd(nums: array of integer): array of integer;
begin
  var res := new integer[nums.Length];

  for var i := 0 to nums.Length - 1 do
  begin
    if nums[i] mod 2 <> 0 then
      res[i] := nums[i] * nums[i]
    else
      res[i] := 0;
  end;

  Result := res;
end;

function GCDLCM(a, b: integer): (integer, integer);
begin
  var c := Max(a, b);
  var d := Min(a, b);
  var t := 1;

  while t > 0 do
  begin
    t := c mod d;
    c := d;
    d := t;
  end;

  var gcd := c;
  var lcm := (a * b) div gcd;

  Result := (gcd, lcm);
end;

function ReorderString(s: string; indices: array of integer): string;
begin
  var resultArr := new char[s.Length];

  for var i := 0 to indices.Length - 1 do
  begin
    resultArr[indices[i]] := s[i + 1];
  end;

  Result := new string(resultArr);
end;

function SimplifyPath(path: string): string;
begin
  var parts := path.Split('/');
  var stack := new Stack<string>;

  for var i := 0 to parts.Length - 1 do
  begin
    if (parts[i] = '') or (parts[i] = '.') then
      continue
    else if parts[i] = '..' then
    begin
      if stack.Count > 0 then
        stack.Pop;
    end
    else
      stack.Push(parts[i]);
  end;

  var resultParts := stack.ToArray;
  &Array.Reverse(resultParts);

  Result := '/' + string.Join('/', resultParts);
end;

function SquareDictionary(numbers: array of integer): Dictionary<integer, integer>;
begin
  var res := new Dictionary<integer, integer>;
  for var i := 0 to numbers.Length - 1 do
  begin
    res[numbers[i]] := numbers[i] * numbers[i];
  end;
  Result := res;
end;

function FindInMatrix(matrix: array of array of integer; target: integer): boolean;
begin
  if (matrix.Length = 0) or (matrix[0].Length = 0) then
  begin
    Result := false;
    exit;
  end;

  var m := matrix.Length;
  var n := matrix[0].Length;

  var row := 0;
  var col := n - 1;

  while (row < m) and (col >= 0) do
  begin
    if matrix[row, col] = target then
    begin
      Result := true;
      exit;
    end
    else if matrix[row, col] < target then
      row += 1
    else
      col -= 1;
  end;

  Result := false;
end;

function KSmallest(arr: array of integer; k: integer): array of integer;
begin
  if (k = 0) or (arr.Length = 0) then
  begin
    Result := new integer[0];
    exit;
  end;

  var sortedArr := arr.ToArray;
  &Array.Sort(sortedArr);

  var res := new integer[k];
  for var i := 0 to k - 1 do
    res[i] := sortedArr[i];

  Result := res;
end;

function BitwiseSubtract(x, y: integer): integer;
begin
  while y <> 0 do
  begin
    var borrow := (not x) and y;
    x := x xor y;
    y := borrow shl 1;
  end;
  Result := x;
end;

function IntervalsIntersection(list1, list2: array of (integer, integer)): array of (integer, integer);
begin
  var res := new List<(integer, integer)>;
  var i := 0;
  var j := 0;

  while (i < list1.Length) and (j < list2.Length) do
  begin
    var start := Max(list1[i].Item1, list2[j].Item1);
    var endVal := Min(list1[i].Item2, list2[j].Item2);

    if start <= endVal then
      res.Add((start, endVal));

    if list1[i].Item2 < list2[j].Item2 then
      i += 1
    else
      j += 1;
  end;

  Result := res.ToArray;
end;

function IsPerfectPower(n: integer): boolean;
begin
  if n < 2 then
  begin
    Result := false;
    exit;
  end;

  for var base := 2 to Trunc(Sqrt(n)) do
  begin
    var exponent := 2;
    while Power(base, exponent) <= n do
    begin
      if Power(base, exponent) = n then
      begin
        Result := true;
        exit;
      end;
      exponent += 1;
    end;
  end;

  Result := false;
end;

function LongestLCIS(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var maxLen := 1;
  var currentLen := 1;

  for var i := 1 to nums.Length - 1 do
  begin
    if nums[i] > nums[i - 1] then
    begin
      currentLen += 1;
      maxLen := Max(maxLen, currentLen);
    end
    else
      currentLen := 1;
  end;

  Result := maxLen;
end;

function IsPowerOf2(n: integer): boolean;
begin
  if n <= 0 then
  begin
    Result := false;
    exit;
  end;

  while n <> 1 do
  begin
    if n mod 2 <> 0 then
    begin
      Result := false;
      exit;
    end;
    n := n div 2;
  end;

  Result := true;
end;

function MatrixAddition(A, B: array[,] of integer): array[,] of integer;
begin
  var n1 := A.GetLength(0);
  var n2 := A.GetLength(1);
  var newA := new integer[n1, n2];

  for var i := 0 to n1 - 1 do
  begin
    for var j := 0 to n2 - 1 do
    begin
      newA[i, j] := A[i, j] + B[i, j];
    end;
  end;

  Result := newA;
end;

function Modes(numbers: array of integer): array of integer;
begin
  var count := new Dictionary<integer, integer>;

  for var i := 0 to numbers.Length - 1 do
  begin
    if count.ContainsKey(numbers[i]) then
      count[numbers[i]] += 1
    else
      count[numbers[i]] := 1;
  end;

  var maxCount := count.Values.Max;
  var res := new List<integer>;

  foreach var pair in count do
  begin
    if pair.Value = maxCount then
      res.Add(pair.Key);
  end;

  res.Sort;
  Result := res.ToArray;
end;

procedure DFS(city: integer; visit: HashSet<integer>; isConnected: array of array of integer);
begin
  visit.Add(city);
  for var another := 0 to isConnected.Length - 1 do
  begin
    if (another <> city) and (isConnected[city, another] = 1) and (not visit.Contains(another)) then
      DFS(another, visit, isConnected);
  end;
end;

function FindCircleNum(isConnected: array of array of integer): integer;
begin
  var visit := new HashSet<integer>;
  var province := 0;
  var n := isConnected.Length;

  for var city := 0 to n - 1 do
  begin
    if not visit.Contains(city) then
    begin
      province += 1;
      DFS(city, visit, isConnected);
    end;
  end;

  Result := province;
end;

function SortAndDeduplicate(lst: array of string): array of string;
begin
  Result := lst.Distinct().Order().ToArray();
end;

function Multiply(mat1, mat2: array [,] of integer): array [,] of integer;
begin
  var m := mat1.GetLength(0);
  var n := mat2.GetLength(1);
  var p := mat1.GetLength(1);
  Result := new integer[m, n];

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      var tmp := 0;
      for var k := 0 to p - 1 do
        tmp += mat1[i, k] * mat2[k, j];
      Result[i, j] := tmp;
    end;
end;

function UnionArray(nums1, nums2: List<integer>): List<integer>;
begin
  nums1.RemoveAll(x -> x = 0);
  nums2.RemoveAll(x -> x = 0);

  var i := 0;
  var j := 0;

  while (i < nums1.Count) and (j < nums2.Count) do
  begin
    if nums1[i] <= nums2[j] then
      i += 1
    else
    begin
      nums1.Insert(i, nums2[j]);
      i += 1;
      j += 1;
    end;
  end;

  if j < nums2.Count then
    nums1.AddRange(nums2.Skip(j));

  Result := nums1;
end;

function MaxFreq(nums: array of integer; k: integer): integer;
begin
  &Array.Sort(nums);
  var left := 0;
  var right := 0;
  var maxFreq := 0;
  var total := 0;

  while right < nums.Length do
  begin
    total += nums[right];
    if nums[right] * (right - left + 1) <= total + k then
      maxFreq := Max(maxFreq, right - left + 1)
    else
    begin
      total -= nums[left];
      left += 1;
    end;
    right += 1;
  end;

  Result := maxFreq;
end;

function RemoveFailingStudents(grades: array of (string, integer)): Dictionary<string, integer>;
begin
  Result := new Dictionary<string, integer>();
  foreach var item in grades do
    if item[1] >= 60 then
      Result[item[0]] := item[1];
end;

function FindLongestZeros(number: integer): integer;
begin
  var binaryStr := Convert.ToString(number, 2);
  var maxGap := 0;
  var currentGap := 0;

  foreach var bit in binaryStr do
  begin
    if bit = '0' then
      currentGap += 1
    else if bit = '1' then
    begin
      if currentGap > maxGap then
        maxGap := currentGap;
      currentGap := 0;
    end;
  end;

  Result := maxGap;
end;

function Factorial(n: integer): integer;
begin
  Result := 1;
  for var i := 2 to n do
    Result *= i;
end;

function SumOfDigitFactorials(n: integer): integer;
begin
  Result := 0;
  foreach var digitChar in n.ToString() do
  begin
    var digit := StrToInt(digitChar);
    Result += Factorial(digit);
  end;
end;

function MostFrequentNumbers(numbers: array of integer): array of integer;
begin
  var freqDict := new Dictionary<integer, integer>();
  foreach var num in numbers do
  begin
    if freqDict.ContainsKey(num) then
      freqDict[num] += 1
    else
      freqDict[num] := 1;
  end;

  var maxCount := freqDict.Values.Max();
  Result := freqDict.Where(x -> x.Value = maxCount).Select(x -> x.Key).ToArray();
end;

function IsPerfect(n: integer): boolean;
begin
  if n = 1 then
  begin
    Result := False;
    exit;
  end;

  var sum := 1;
  var i := 2;
  while i <= n / i do
  begin
    if n mod i = 0 then
      sum += i + (n div i);
    i += 1;
  end;

  if i * i = n then
    sum -= i;

  Result := sum = n;
end;

function FindPerfectNumbers(startVal, endVal: integer): array of integer;
begin
  var perfectNumbers := new List<integer>();

  for var num := startVal to endVal do
    if IsPerfect(num) then
      perfectNumbers.Add(num);

  Result := perfectNumbers.ToArray();
end;

function CountSetBits(n: integer): integer;
begin
  var count := 0;
  var temp := n;
  while temp > 0 do
  begin
    count += temp and 1;
    temp := temp shr 1;
  end;
  Result := count;
end;

function LengthLongestSubstring(s: string): integer;
begin
  var charMap := new Dictionary<char, integer>();
  var left := 0;
  var maxLength := 0;

  for var right := 0 to s.Length - 1 do
  begin
    var currentChar := s[right + 1];
    if charMap.ContainsKey(currentChar) then
      left := Max(left, charMap[currentChar] + 1);

    charMap[currentChar] := right;
    maxLength := Max(maxLength, right - left + 1);
  end;

  Result := maxLength;
end;

function SecondLargestDigit(s: string): integer;
begin
  var digits := new List<integer>();
  foreach var c in s do
    if c.IsDigit() then
      digits.Add(StrToInt(c));

  var uniqueDigits := digits.Distinct().Order().ToArray();
  if uniqueDigits.Length < 2 then
    Result := -1
  else
    Result := uniqueDigits[uniqueDigits.Length - 2];
end;

function FindCombinations(nums: array of integer; k: integer): List<array of integer>;
begin
  if nums.Length < k then
  begin
    Result := new List<array of integer>();
    exit;
  end;

  if nums.Length = k then
  begin
    Result := new List<array of integer>();
    Result.Add(nums);
    exit;
  end;

  if k = 1 then
  begin
    Result := new List<array of integer>();
    foreach var x in nums do
      Result.Add(|x|);
    exit;
  end;

  Result := new List<array of integer>();
  for var i := 0 to nums.Length - 1 do
  begin
    var remaining := nums.Skip(i + 1).ToArray();
    var subsets := FindCombinations(remaining, k - 1);
    foreach var subset in subsets do
    begin
      var newComb := new integer[subset.Length + 1];
      newComb[0] := nums[i];
      for var j := 0 to subset.Length - 1 do
        newComb[j + 1] := subset[j];
      Result.Add(newComb);
    end;
  end;
end;

function DpCountPattern(i, j: integer; text, pattern: string; lenText, lenPattern: integer): integer;
begin
  if j = lenPattern then
    Result := 1
  else if i = lenText then
    Result := 0
  else if text[i + 1] = pattern[j + 1] then
    Result := DpCountPattern(i + 1, j + 1, text, pattern, lenText, lenPattern) + DpCountPattern(i + 1, j, text, pattern, lenText, lenPattern)
  else
    Result := DpCountPattern(i + 1, j, text, pattern, lenText, lenPattern);
end;

function CountPatternAsSubsequence(text, pattern: string): integer;
begin
  var lenText := text.Length;
  var lenPattern := pattern.Length;
  Result := DpCountPattern(0, 0, text, pattern, lenText, lenPattern);
end;

function ConvertSigns(nums: array of integer): array of integer;
begin
  Result := new integer[nums.Length];
  for var i := 0 to nums.Length - 1 do
  begin
    if nums[i] > 0 then
      Result[i] := 1
    else if nums[i] < 0 then
      Result[i] := -1
    else
      Result[i] := 0;
  end;
end;

function MinChangesAlternating(s: string): integer;
begin
  var count1 := 0;
  var count2 := 0;

  for var i := 0 to s.Length - 1 do
  begin
    if i mod 2 = 0 then
    begin
      if s[i + 1] <> '1' then
        count1 += 1
      else
        count2 += 1;
    end
    else
    begin
      if s[i + 1] <> '1' then
        count2 += 1
      else
        count1 += 1;
    end;
  end;

  Result := Min(count1, count2);
end;

function LargestPositive(numbers: array of integer): integer;
begin
  var positiveNumbers := numbers.Where(x -> x >= 0).ToArray();
  if positiveNumbers.Length = 0 then
    raise new System.ArgumentException('No positive numbers in the list')
  else
    Result := positiveNumbers.Max();
end;

function FindCycleSize(node: integer; var localInDegree: array of integer; edges: array of integer): integer;
begin
  if localInDegree[node] = 0 then
  begin
    Result := 0;
    exit;
  end;

  localInDegree[node] -= 1;
  Result := 1 + FindCycleSize(edges[node], localInDegree, edges);
end;

function LongestCycle(edges: array of integer): integer;
begin
  var inDegree := new integer[edges.Length];
  var queue := new Queue<integer>();

  for var i := 0 to edges.Length - 1 do
    if edges[i] <> -1 then
      inDegree[edges[i]] += 1;

  for var i := 0 to edges.Length - 1 do
    if inDegree[i] = 0 then
      queue.Enqueue(i);

  while queue.Count > 0 do
  begin
    var node := queue.Dequeue();
    if edges[node] <> -1 then
    begin
      inDegree[edges[node]] -= 1;
      if inDegree[edges[node]] = 0 then
        queue.Enqueue(edges[node]);
    end;
  end;

  var maxCycle := -1;
  var tempInDegree := Copy(inDegree);
  for var i := 0 to edges.Length - 1 do
  begin
    if tempInDegree[i] <> 0 then
    begin
      var cycleSize := FindCycleSize(i, tempInDegree, edges);
      if cycleSize > maxCycle then
        maxCycle := cycleSize;
    end;
  end;

  Result := maxCycle;
end;
